SET NAMES utf8mb4;

UPDATE destinations
SET excerpt = 'A mountain you climb before dawn to watch the sun crack the horizon. Sri Lanka''s most sacred peak draws pilgrims and hikers alike.',
    intro = 'Adam''s Peak — or Sri Pada, depending who you ask — rises 2,243 metres above the central highlands. Everyone comes for the same reason: sunrise from the top. The climb takes three to five hours depending on your legs and how many tea breaks you take. Pilgrim season runs December to May, when the crowds string lanterns along the trail like a river of light. Outside that window the path is quieter, but the weather''s less reliable. You''ll share the summit with monks, tourists, and families who''ve been making this trek for generations.',
    why_visit = 'The silhouette of the peak against a pink dawn is something photos don''t capture. There''s a moment just before the sun appears when the whole crowd goes quiet. That''s why you''re here. The giant footprint-shaped depression at the top matters too — Buddhist, Hindu, Muslim, and Christian traditions each claim it. You don''t need to be religious to feel the weight of that.',
    things_to_do = 'Start the climb from Dalhousie (Nallathanniya) around 2 AM. Take a headlamp — the path is well-marked but unlit. Count the steps if you like; there are about 5,500 of them. Vendors sell hot tea and snacks at regular intervals all the way up. Watch the sunrise from the top, ring the bell, visit the footprint shrine. Coming down takes two hours and is harder on the knees than going up.',
    best_time = 'December to May is pilgrimage season. December and January are busiest — expect queues on the summit. February and March offer the best balance of clear skies and manageable crowds. April can get hot. The off-season (June to November) means rain, leeches, and sometimes a closed path. If you want solitude and don''t mind getting wet, try September.',
    how_to_get_there = 'From Colombo, take the Hatton road (A7) about 150 kilometres. Turn off at Maskeliya for Dalhousie. Buses run from Colombo to Hatton, then a local bus to Dalhousie. The train from Colombo to Hatton is scenic but slow — book a seat in advance.',
    suggested_itinerary = 'Arrive in Dalhousie by evening. Sleep early. Wake at 1:30 AM, start climbing by 2. Sunrise is around 6 AM. Back down by 9, breakfast, then onward to Nuwara Eliya or Kandy for the afternoon. You don''t need more than one night here unless you want to explore the surrounding tea country.',
    where_to_stay = 'Dalhousie has basic guesthouses and a couple of mid-range hotels. Expect hot water to be unreliable. The Slightly Chilled Guesthouse is popular with backpackers. For something better, stay in Hatton or Maskeliya and drive to the trailhead. There''s nothing luxurious near the base — this is a pilgrimage town, not a resort.',
    travel_tips = 'Rent a headlamp in Dalhousie if you didn''t bring one. Bring a light jacket — the summit is cold even in warm months. The tea from stalls along the way is sugary and perfect. Don''t wear new shoes. Take cash, card machines are rare above the halfway point.',
    nearby_travel_times = 'Hatton: 45 minutes by bus. Nuwara Eliya: 1.5 hours. Kandy: 3 hours. Colombo: 4 hours.',
    works_well_with = 'Nuwara Eliya, Hatton, Kandy',
    cta_text = 'Ready to see the sunrise from Sri Pada? We''ll sort the logistics — you just bring the legs.',
    faq_json = '[{"q":"Is the climb dangerous?","a":"Not really. The steps are uneven in spots and it gets steep near the top. Take your time and watch your footing."},{"q":"Do I need a guide?","a":"No. The path is straightforward and packed with people during season."},{"q":"Can children do the climb?","a":"Fit kids from about 10 up can manage. Smaller children will need carrying on some sections."}]'
WHERE slug = 'sri-pada-adams-peak'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'A horseshoe bay on Sri Lanka''s south coast where the waves roll in gentle and the cafes are carved into the cliff.',
    intro = 'Hiriketiya is what happens when a sleepy fishing cove meets a wave of surfers and digital nomads. The bay is small — you can swim across it in a few minutes — but the vibe is outsized. Palms lean over the sand. A headland on one side shelters the beach from the worst of the swell. The reef breaks left and right, which is why surfers keep coming back. Development has crept in fast over the last five years. You''ll find good pizza, cold beer, and Wi-Fi that mostly works.',
    why_visit = 'The bay itself. There''s no other beach on the south coast that feels quite this contained and friendly. The surf is beginner-friendly most of the year. When you''re not in the water, you can lie in a hammock and watch someone else catch their first wave. It''s smaller and less commercial than Mirissa or Weligama, though that''s changing.',
    things_to_do = 'Surfing is the main event. Rent a board from one of the shacks on the beach — they''ll give you a quick lesson too. Walk over the headland to Dickwella beach at low tide. Eat at the Shipwreck Cafe, which is built into the rocks. Do a yoga session at one of the retreat centres. Drink king coconut on the beach and do nothing. That''s the point.',
    best_time = 'November to April: flat water, blue skies, perfect for beginners. May to October: the swell picks up, the water gets rougher, and the bay empties out. If you''re an experienced surfer, the monsoon season actually delivers better waves. The beach is almost empty then.',
    how_to_get_there = 'From Colombo, take the Southern Expressway to Matara (about 2.5 hours), then drive east along the coast road for 30 minutes. Buses run from Matara to Dickwella, then a tuk-tuk to the bay. The nearest train station is Matara.',
    suggested_itinerary = 'Two to four days is plenty. Surf in the morning, eat lunch at a cliffside cafe, nap, surf again in the late afternoon. Do the sunset walk to Dickwella at least once. If you''re staying longer, take a day trip to the Dondra Head lighthouse or the blowholes at Hummanaya.',
    where_to_stay = 'Lots of boutique guesthouses and villas have popped up along the hillside above the bay. Surf Colony is a solid mid-range option. The Hideaway has nicer rooms but is a longer walk to the beach. Budget travellers should try the dorm at Salt House. Book ahead between December and March.',
    travel_tips = 'Bring reef-safe sunscreen — the bay is a marine protected area. Cash is king; not every cafe takes cards. The beach gets crowded on weekends with locals from Matara. Don''t leave valuables on the sand while you swim.',
    nearby_travel_times = 'Dickwella: 10 minutes on foot over the headland. Matara: 30 minutes. Mirissa: 20 minutes. Galle: 1.5 hours.',
    works_well_with = 'Weligama, Mirissa, Tangalle',
    cta_text = 'We know a quiet villa above the bay. One bedroom, open-air bathroom, and a view that never gets old.',
    faq_json = '[{"q":"Is Hiriketiya good for beginner surfers?","a":"Yes. The inside break is mellow and sandy. Lessons are cheap — around 2000 LKR for an hour."},{"q":"Is there nightlife?","a":"Not really. A few bars with music until midnight. It''s more of a chill spot."},{"q":"Can I swim here outside surf season?","a":"The bay is sheltered so it''s swimmable year-round. Just watch for rips near the headland."}]'
WHERE slug = 'hiriketiya'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'A small hill town that became famous for a train ride through tea plantations. The Nine Arch Bridge is here too.',
    intro = 'Ella sits at about 1,000 metres in the central highlands, surrounded by tea estates and cloud forest. Its reputation exploded on Instagram, and honestly? It deserves some of the hype. The train ride from Kandy to Ella is one of the most beautiful in the world. The town itself is a single main street of guesthouses, restaurants, and souvenir shops. It''s touristy. It''s also lovely. The climate is cool enough that you''ll want a jumper in the evening, warm enough that you''ll peel it off by midday.',
    why_visit = 'The train ride is the headline — seven hours of tea plantations, misty valleys, and cliffside tracks. But Ella rewards you for staying put too. Little Adam''s Peak is a gentle hour-long hike with big views. Ella Rock is tougher and quieter. The Nine Arch Bridge is genuinely impressive, though you''ll be sharing the photo spot with fifty other people. The food scene punches above its weight: good Sri Lankan curry, proper coffee, and roti that''ll ruin you for roti anywhere else.',
    things_to_do = 'Do the Kandy-to-Ella train journey one way (book an observation car seat in advance). Hike Little Adam''s Peak for sunrise. Walk the railway tracks to the Nine Arch Bridge — check the train timetable first so you don''t get caught. Do the full Ella Rock hike (about 4 hours round trip). Visit a tea factory — Halpewatte or Uva Halpewatte are both close. Go zip-lining at Flying Ravana. Eat roti at Chill Cafe.',
    best_time = 'January to March is the sweet spot: clear skies, good visibility, cool mornings. April and May get rain. The monsoon hits hard from October to December. Ella works year-round but you''ll get more mist and less view in the wet months.',
    how_to_get_there = 'The train from Kandy is the classic route — about 7 hours, stunning. Trains from Colombo to Badulla stop at Ella station. By car, take the A5 highway from Colombo through Ratnapura and Bandarawela — about 5 hours. Buses run from Colombo, Kandy, and Nuwara Eliya.',
    suggested_itinerary = 'Spend two nights. Day one: arrive by train, settle in, walk to the Nine Arch Bridge. Day two: early morning hike up Little Adam''s Peak, afternoon tea factory visit, evening chill. Day three: Ella Rock hike if you''re keen, then onward to Nuwara Eliya or down to the south coast.',
    where_to_stay = 'Ella has accommodation at every price point. 98 Acres Resort is the splurge — amazing views, infinity pool. The Barn by they are mid-range and stylish. For budget, Chill Ville or Ella Flower Garden are reliable. Book months ahead for December through March.',
    travel_tips = 'The train observation car sells out weeks ahead — book online. The dining car serves decent lunch if you''re doing the full journey. Don''t stand on the train steps for photos; people fall. The walk from Ella station to town is uphill. Pack light.',
    nearby_travel_times = 'Bandarawela: 20 minutes. Nuwara Eliya: 2 hours. Kandy: 3 hours by train, 4 by road. Colombo: 5 hours.',
    works_well_with = 'Nuwara Eliya, Kandy, Bandarawela',
    cta_text = 'We can book the train tickets, the hikes, and a room with a view. Ella is easier when someone else handles the details.',
    faq_json = '[{"q":"How long is the train ride from Kandy to Ella?","a":"About 7 hours. It''s slow, scenic, and worth every minute."},{"q":"Is Ella worth visiting if I don''t hike?","a":"Yes. The town itself, the food, the climate, and just watching the mist roll through the valley are enough."},{"q":"Do I need a guide for Ella Rock?","a":"Not essential but the trail is unmarked in places. Locals offer guiding for a small fee."}]'
WHERE slug = 'ella'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'An ancient rock fortress rising 200 metres above the jungle. Frescoes, mirror walls, and a lion staircase that survives in name only.',
    intro = 'Sigiriya is the kind of place that makes you wonder how they did it without helicopters. A massive rock monolith juts out of the flat jungle, topped with the ruins of a 5th-century palace. King Kashyapa built it as his stronghold. It didn''t work — he lost the battle and died. But the fortress remained. The climb is 1,200 steps up a series of galleries and staircases. The frescoes of celestial maidens — the Sigiriya Damsels — have survived for 1,500 years. The mirror wall still holds graffiti from ancient visitors. And the lion''s paw at the entrance is all that''s left of the grand gateway. It''s the most famous single site in Sri Lanka for good reason.',
    why_visit = 'The scale of it. You walk through formal water gardens at the base, climb through boulder shelters with spiral staircases, pass the frescoes on a sheltered walkway, and finally emerge on the flat summit. The view is enormous — jungle in every direction, the distant bulk of the Knuckles range. It''s a UNESCO World Heritage site and it earns the status. Crowds are the main problem. Go early or go late.',
    things_to_do = 'Climb the rock. Spend time in the water gardens — they''re easy to rush past but worth a slow walk. Visit the Sigiriya Museum at the entrance for context. Explore the boulder caves and the Cobra Hood Cave. Walk or cycle to Pidurangala Rock for the sunset view of Sigiriya itself (a separate ticket, much cheaper, less crowded).',
    best_time = 'Go at 7 AM when the gates open. The light is good, the heat is manageable, and the tour groups haven''t arrived yet. Late afternoon (after 3 PM) works too. Avoid midday — the rock gets scorching. The dry season (January to September) is best. October to December brings afternoon rain.',
    how_to_get_there = 'Sigiriya is about 170 kilometres from Colombo, about 4 hours by car. Take the A1 to Dambulla, then the A9 to Inamaluwa, then turn off. Buses run from Colombo to Dambulla, then a local bus or tuk-tuk the remaining 20 kilometres.',
    suggested_itinerary = 'Arrive the evening before and stay near the rock. Wake early, climb Sigiriya at 7 AM. You''ll be done by 9:30. Spend midday at the museum, then rest. Head to Pidurangala for sunset. That''s one full day. The next morning visit Dambulla Cave Temple and head to Kandy.',
    where_to_stay = 'There are resorts around the base of the rock. Jetwing Vil Uyana is the luxury choice — overwater bungalows in a manmade wetland. Ali Adi Guesthouse is good value. Kalaru Safari Lodge is mid-range with a pool. Stay somewhere with air conditioning; it gets hot.',
    travel_tips = 'Buy water at the base, not at the top — three times the price up there. Monkeys will steal anything shiny or edible. The stairs are steep near the top and the handrail is a metal bar bolted into the rock. Not ideal for anyone with vertigo.',
    nearby_travel_times = 'Dambulla: 20 minutes. Polonnaruwa: 1 hour. Kandy: 2.5 hours. Colombo: 4 hours.',
    works_well_with = 'Dambulla, Polonnaruwa, Kandy',
    cta_text = 'We can get you up the rock before the crowds hit. Early entry, good guide, and a driver who knows the back roads.',
    faq_json = '[{"q":"Is Sigiriya worth the entrance fee?","a":"Yes. It''s expensive by Sri Lankan standards ($30 USD) but there''s nothing else like it."},{"q":"Can I climb Sigiriya in flip-flops?","a":"You can but you won''t enjoy it. Wear proper shoes for the upper sections."},{"q":"How long does it take to climb?","a":"Most people take 45 minutes to an hour going up, 30 minutes coming down."}]'
WHERE slug = 'sigiriya'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'The cultural capital of the hill country. Temples, a lake, and the best roti in Sri Lanka.',
    intro = 'Kandy is Sri Lanka''s second city and the last capital of the ancient kings. It''s built around a lake that was dug by a king who then drowned his wife in it — that''s the kind of history you get here. The Tooth Relic Temple sits on the north shore, the most important Buddhist shrine in the country. The city is noisy, congested, and alive. Markets spill onto the streets. Tuk-tuks swarm like bees. The hills rise green on every side. People either love Kandy or find it too chaotic. Both reactions are fair.',
    why_visit = 'The Temple of the Tooth is the reason most people come. But Kandy rewards you for poking around. The Royal Botanical Gardens in Peradeniya are 10 minutes away and genuinely beautiful. The Kandyan dance performances are touristy but fun. The market is a maze of spice, fruit, and textile stalls. And the food — Kandy has the best string-hopper kottu in the country, and I will fight anyone who disagrees.',
    things_to_do = 'Visit the Temple of the Tooth (go early or during puja for the atmosphere). Walk around Kandy Lake. Explore the markets near the clock tower. Take a half-day trip to Peradeniya Botanical Gardens. See a Kandyan dance performance at the Arts Association or the Temple. Ride the train to Ella or Nuwara Eliya. Eat kottu roti at Devi''s or the Devon Restaurant.',
    best_time = 'Kandy is cool year-round thanks to its 500-metre elevation. The main festival is Esala Perahera in July or August — spectacular but the city is packed and prices triple. January to April has the best weather. October to December is wet.',
    how_to_get_there = 'Three hours from Colombo by car (A1 highway). Trains from Colombo to Kandy run several times daily — about 2.5 hours. The train is the better choice. Buses from Colombo''s Bastian Mawatha terminal run 24/7.',
    suggested_itinerary = 'Two days is right. Day one: Temple of the Tooth in the morning, Peradeniya Gardens in the afternoon. Day two: morning market crawl, then catch the train to Ella or Nuwara Eliya. If you have extra time, take a detour to the Knuckles range for a day hike.',
    where_to_stay = 'The city centre is loud. Stay in the hills above the lake for quiet. Earl''s Regency is a solid four-star. Kandy House is boutique and historic. For budget, the backpacker area near the station has dozens of guesthouses. Book during Perahera or Christmas.',
    travel_tips = 'Tuk-tuk drivers will overcharge you. Use PickMe or Uber instead. The Temple of the Tooth has a strict dress code — cover shoulders and knees. You WILL get stuck in traffic; build buffer time into any plan. The lake smells a bit in the dry season; that''s normal.',
    nearby_travel_times = 'Peradeniya: 10 minutes. Matale: 30 minutes. Nuwara Eliya: 2 hours. Sigiriya: 2.5 hours. Colombo: 3 hours.',
    works_well_with = 'Sigiriya, Nuwara Eliya, Ella, Knuckles Mountain Range',
    cta_text = 'Let us plan your Kandy days — temple timing, traffic-proof routes, and that kottu place the guides never mention.',
    faq_json = '[{"q":"Is the Temple of the Tooth worth seeing?","a":"Yes. The relic itself is in a golden casket you can''t see, but the ritual, the architecture, and the atmosphere are worth it."},{"q":"When is the best time to visit the temple?","a":"During puja (5:30 AM, 9:30 AM, 6:30 PM). That''s when the doors open and the ceremonies happen."},{"q":"Can I take photos inside?","a":"Yes in the main halls, no in the inner sanctum during puja."}]'
WHERE slug = 'kandy'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'Sri Lanka''s most famous national park. Leopards, elephants, and jeeps that start lining up before dawn.',
    intro = 'Yala National Park covers nearly 1,000 square kilometres of dry zone wilderness. It''s the place everyone comes to see leopards. And you probably will see one — Yala has the highest density of leopards in the world. The park is divided into blocks, with Block 1 being the most visited. Too visited, honestly. During peak season the jeeps queue up like traffic on the A4. But when one of those jeeps spots a leopard lounging in a tree, the queue doesn''t matter. The sightings are that good. Beyond the cats, there are elephants, sloth bears, crocodiles, and so many peacocks you''ll stop noticing them.',
    why_visit = 'The leopard sightings are world-class. Period. But Yala isn''t just a safari park — the landscape is dramatic. Dry scrub gives way to rocky outcrops, waterholes, and a coastline of beaches where turtles nest. The park has ancient ruins too: a rock temple and a monastery complex that predate the wildlife reserve. Most jeeps speed past them. Don''t.',
    things_to_do = 'Do a full-day safari (half-day feels rushed). Visit the Sithulpawwa rock temple on the park boundary. Walk the beach at Patanangala — you can''t swim here (crocodiles) but it''s wild and empty. Take a jeep to the Yala Beach for the sunset game drive. Birdwatch: 215 species including the Sri Lankan junglefowl and the painted stork.',
    best_time = 'February to June is prime for leopards. The park closes for the dry season from September to October (dates vary, check ahead). The wet season (November to January) is lush but wildlife is harder to spot. July and August are busy and dusty.',
    how_to_get_there = 'Yala''s main entrance is at Tissamaharama, about 290 kilometres from Colombo — five hours by car. From the south coast (Mirissa, Weligama) it''s about 2.5 hours. You can fly to Hambantota airport but it''s not much faster door-to-door.',
    suggested_itinerary = 'Base yourself in Tissamaharama for two nights. Do an evening safari on arrival day, a full-day safari the next day. Use the afternoon for Sithulpawwa or just sit by your hotel pool. The third morning, head to the coast or up to Udawalawe for a different park.',
    where_to_stay = 'Tissamaharama has everything from luxury tented camps to basic guesthouses. Wild Coast Tented Lodge is the splurge — Colombo-worthy prices but an incredible experience. Kulu Safaris is mid-range and reliable. For budget, Lake View Cottages. Stay somewhere with a pool; you''ll need it after a dusty safari.',
    travel_tips = 'Book your jeep and driver in advance — quality varies enormously. Good drivers know the cats'' territories. Bad drivers speed past everything. The park gets busy; start before 5 AM to be first at the gates. No, really. 5 AM. Take a face mask for the dust.',
    nearby_travel_times = 'Tissamaharama: 10 minutes to gate. Tangalle: 1.5 hours. Mirissa: 2 hours. Ella: 3 hours. Colombo: 5 hours.',
    works_well_with = 'Udawalawe, Tangalle, Mirissa, Ella',
    cta_text = 'We know the drivers who know the leopards. Safari logistics, park permits, and a cold drink waiting when you get back.',
    faq_json = '[{"q":"Will I definitely see a leopard?","a":"No guarantee, but Yala has the best odds in the world. Most visitors see at least one."},{"q":"Are the safaris dusty?","a":"Yes. Wear a buff or mask, and leave the white clothes at home."},{"q":"Can I enter the park without a jeep?","a":"No. Private vehicles aren''t allowed inside. You must book a safari jeep with a driver."}]'
WHERE slug = 'yala'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'The commercial capital — chaotic, loud, and more interesting than people give it credit for.',
    intro = 'Colombo is where most trips to Sri Lanka begin and end. It''s not a resort city. It''s a working port city with traffic jams, colonial buildings crumbling next to glass towers, and some of the best food in the country. Most travellers rush through it. That''s a mistake. The Pettah market district is a sensory overload in the best way: spices, textiles, electronics, and street food spilling onto every pavement. Galle Face Green fills with families flying kites at sunset. The cinnamon-coloured Dutch-era buildings in the Fort district echo with 400 years of colonial history. It''s hot, loud, and genuinely alive.',
    why_visit = 'The food alone justifies a stop. Colombo has Sri Lanka''s best restaurants — Ministry of Crab, Nuga Gama, Kaema Sutra. The street food scene in Pettah is even better. The museums are solid: the National Museum is excellent, and the Dutch Museum is housed in a 17th-century mansion. The Gangaramaya Temple is eclectic and wonderful. And there''s something about a city that has a beach, a fort, a stock exchange, and a cricket ground all within a few kilometres.',
    things_to_do = 'Walk Pettah market in the morning before the heat peaks. Visit the Gangaramaya Temple and its odd little museum. Have lunch at a crab restaurant. Stroll Galle Face Green at sunset. Visit the Colombo National Museum. Explore the Dutch Hospital precinct for shopping and dining. Catch a cricket match at the R. Premadasa Stadium if there''s a game on. Take a tuk-tuk to Mount Lavinia for a swim.',
    best_time = 'Colombo is hot year-round. December to April is the driest. May to August brings the monsoon — afternoon downpours that clear the streets. September to November is another wet spell. If you time the rain right, the city empties out and the light is beautiful.',
    how_to_get_there = 'Colombo is the main entry point. Bandaranaike International Airport is 35 kilometres north in Katunayake. The expressway from the airport to the city takes about 40 minutes. Trains and buses connect Colombo to every major town in Sri Lanka. The Fort Railway Station is the main hub.',
    suggested_itinerary = 'One or two full days is enough. Day one: Pettah in the morning, Gangaramaya and Galle Face in the afternoon, dinner at a Colombo restaurant. Day two: Museum in the morning, then escape to the hills or the coast. Don''t over-plan Colombo. It''s a city to wander, not a checklist.',
    where_to_stay = 'Colombo has proper hotels. The Kingsbury and Shangri-La are the big ones on Galle Road. For boutique, try The Wallawwa (near the airport but lovely) or Residence by Uga. Budget travellers should look at Colombo Court or backpacker hostels near Fort. Stay in Colombo 3 or 4 for convenience.',
    travel_tips = 'Use Uber or PickMe for getting around. Tuk-tuks will quote triple the price. The airport is farther from the city than it looks on a map — leave two hours for the trip. The seafood at the Dutch Hospital is overpriced for what it is. The best food in Colombo is in the side streets of Pettah, not in the tourist restaurants.',
    nearby_travel_times = 'Negombo: 40 minutes. Mount Lavinia: 20 minutes. Galle: 1.5 hours. Kandy: 3 hours.',
    works_well_with = 'Negombo, Galle, Kandy',
    cta_text = 'We can arrange a Colombo food tour that doesn''t hit the tourist traps. Or just a driver to get you out of the city smoothly.',
    faq_json = '[{"q":"Is Colombo safe for tourists?","a":"Yes, very. Take normal city precautions with valuables. The main risks are traffic and touts."},{"q":"How many days do I need in Colombo?","a":"One or two. It''s not the main attraction but it''s worth a proper day."},{"q":"Can I swim at Colombo beaches?","a":"Galle Face is not a swimming beach. Mount Lavinia is swimmable but the water quality varies."}]'
WHERE slug = 'colombo'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'A walled fort city on the south coast where Dutch colonial architecture meets modern boutique hotels.',
    intro = 'Galle is the most handsome city in Sri Lanka. The Dutch Fort covers 36 hectares of cobbled streets, colonial mansions, and a sea wall that has held back the Indian Ocean for 400 years. Inside the walls, it''s a different world — art galleries, cafes, boutique hotels, and the odd working lighthouse. Outside the walls, the city of Galle proper is a busy Sri Lankan town with markets, bus stands, and traffic. The contrast is part of the charm. The Fort survived the 2004 tsunami where much of the outer city was destroyed. That gives it a weight that goes beyond the prettiness.',
    why_visit = 'The Fort is the obvious draw. Walking ramparts at sunset with the ocean on one side and the old city on the other is one of Sri Lanka''s great experiences. But Galle is also a base for the south coast: Unawatuna is ten minutes away, the south coast beaches stretch east, and the whale-watching in Mirissa is an hour down the road. The food scene is excellent. The shopping is better than anywhere outside Colombo.',
    things_to_do = 'Walk the entire Fort rampart — start at the Galle Lighthouse and go clockwise. Explore the streets inside the Fort: Church Street, Leyn Baan Street, Pedlar Street. Visit the National Maritime Museum. Have a gin and tonic at the Galle Fort Hotel. Watch a cricket match at the Galle International Stadium — one of the most beautiful cricket grounds in the world. Learn to make rice and curry at a cooking class. Buy gems at the Old Dutch Market if you know what you''re looking at.',
    best_time = 'November to April is the dry season on the south coast. Galle is pleasant year-round but the monsoon (May to September) brings rain, rough seas, and empty streets. For photographers, the light in January is incredible.',
    how_to_get_there = 'About 120 kilometres from Colombo on the Southern Expressway — 1.5 hours by car. Trains from Colombo to Galle run hourly (2.5 hours, scenic). The coastal road is slower but prettier.',
    suggested_itinerary = 'Two nights is the minimum. Day one: arrive, walk the ramparts, explore the Fort. Day two: morning at the market, afternoon at a beach (Unawatuna or Jungle Beach), sunset back on the ramparts. Day three: head east along the coast or back to Colombo.',
    where_to_stay = 'The Fort is expensive but worth it. Amangalla is the legend — 17th-century Dutch mansion, absurdly elegant. The Galle Fort Hotel is also top-tier. For mid-range, Fort Bazaar or Mango House. Inside the Fort nothing is cheap. If budget matters, stay outside the walls in Galle town or nearby Unawatuna.',
    travel_tips = 'The best restauants inside the Fort book out weeks ahead. Plan your dinners. The Fort streets are cobbled — don''t bring a wheelie suitcase. The shops close by 7 PM inside the walls. Stroll early morning when the tourists are still in bed.',
    nearby_travel_times = 'Unawatuna: 10 minutes. Hikkaduwa: 30 minutes. Mirissa: 1 hour. Colombo: 1.5 hours.',
    works_well_with = 'Unawatuna, Hikkaduwa, Mirissa, Colombo',
    cta_text = 'We have a curated guide to Galle — the rampart walk, the hidden courtyard bars, and the best Sunday roast on the island.',
    faq_json = '[{"q":"Do I need more than one day in Galle?","a":"Yes. The Fort alone needs a day. Add another for the beaches and food scene."},{"q":"Can I drive inside the Fort?","a":"Yes but parking is limited and the streets are narrow. Walking is better."},{"q":"Is Galle expensive?","a":"The Fort is pricey by Sri Lankan standards. Eating and sleeping inside the walls costs Colombo money."}]'
WHERE slug = 'galle'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'A hill station where the British built a town that still feels like an English country garden in the tropics.',
    intro = 'Nuwara Eliya sits at 1,868 metres, surrounded by tea plantations that roll over hills like green corduroy. The British planters who settled here called it Little England. They built mock-Tudor cottages, planted roses, played golf, and pretended they weren''t in the tropics. The pretence survives. The racecourse runs one day a year. The golf course is still open. The lake in the middle of town is ringed with jacaranda trees. It''s cold at night — the coldest place in Sri Lanka. And the tea that grows around here is the best in the country.',
    why_visit = 'The tea estates are the real draw. Most people ride the train from Kandy or Ella and watch the plantations roll past the window. Getting out into them is better. You can tour a factory, walk through the fields, and drink a cup of single-estate Ceylon tea at the source. Nuwara Eliya town itself is a bit of a mess — crumbling colonial buildings, bad traffic, and a roundabout that defies logic. But the surrounding countryside is gorgeous. Gregory Lake is nice for a paddleboat ride. The hike to Single Tree Hill gives you a view over the whole valley.',
    things_to_do = 'Tour a tea factory — Pedro Tea Estate or Blue Field Tea Gardens (more touristy but closer). Walk through the tea plantations at dawn. Visit the Hakgala Botanical Gardens. Paddleboat on Gregory Lake. Drive to the Laxapana Falls. Hike to Single Tree Hill. Visit the old Hill Club for a gin and tonic if you''re dressed for it. Buy tea leaves directly from a factory shop.',
    best_time = 'January to April is the dry season — clear skies, good light, decent temperatures. It still gets cold at night (single digits). May to August brings the monsoon mist. September to November is unpredictable. Whenever you come, pack a jumper and a raincoat.',
    how_to_get_there = 'From Colombo, the A1 highway to Kandy then the A5 up the mountain — about 4 hours. The train from Colombo to Nanu Oya (the nearest station) takes about 5 hours, then a tuk-tuk up to Nuwara Eliya. The train from Ella is about 2 hours in the other direction.',
    suggested_itinerary = 'Two nights is enough. Day one: arrive by train, afternoon tea factory visit. Day two: morning walk in the plantations, Hakgala Gardens, paddleboat on the lake. Day three: head down to Ella or Kandy. The drive out of Nuwara Eliya is one of the most scenic routes in the country.',
    where_to_stay = 'The Grand Hotel is the old-style colonial experience — creaky floors, fireplaces, overpriced but charming. Jetwing Warwick Gardens is a plantation bungalow conversion. For budget, the area around the bus station has basic guesthouses. Stay somewhere with heating; you''ll need it at night.',
    travel_tips = 'The weather changes fast. Sunny morning, freezing rain by lunch. The tea you buy at the airport gift shop is not the same as factory-direct. The Hill Club requires men to wear jackets after 6 PM. Don''t swim in Gregory Lake. It''s not clean.',
    nearby_travel_times = 'Nanu Oya station: 15 minutes. Hakgala: 20 minutes. Horton Plains: 1 hour. Kandy: 2 hours. Ella: 2 hours.',
    works_well_with = 'Ella, Kandy, Horton Plains',
    cta_text = 'We can book tea factory tours that skip the tourist queues and take you to the estates the buses don''t visit.',
    faq_json = '[{"q":"Do I need warm clothes?","a":"Yes. Nights drop to 5-10°C. A fleece and a windbreaker will do."},{"q":"Is the train journey the best way to arrive?","a":"The train from Kandy or Ella is beautiful. By car you get more flexibility and better photo stops."},{"q":"Can I pick my own tea leaves?","a":"Some estates let you try it. The workers make it look easy until you try to fill a basket."}]'
WHERE slug = 'nuwara-eliya'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'A palm-fringed beach where the party scene has matured but the waves are still the main attraction.',
    intro = 'Mirissa is the south coast''s original backpacker beach. It got discovered in the 2000s, went through a party phase, and settled into something more comfortable. You still get fire shows and full-moon parties but the vibe is mellower than the reputation suggests. The beach is a long curve of golden sand with a rocky headland at one end. Palms lean over the shore. A reef protects the bay so the water is usually calm. The whales pass offshore from November to April, and the whale-watching industry is a big draw. It''s not undiscovered and it''s not quiet. But it''s the most reliable good-beach experience on the south coast.',
    why_visit = 'The whale-watching is world-class — blue whales, sperm whales, and pods of spinner dolphins. The sand is good, the swimming is safe, and the sunset from Coconut Tree Hill is postcard-perfect. The food scene runs from cheap roti shops to proper seafood restaurants. And the Parrot Rock crossing at high tide is a fun little adventure.',
    things_to_do = 'Go whale-watching (book a smaller boat for a better experience). Relax on the main beach. Walk to Coconut Tree Hill for sunset. Wade out to Parrot Rock at low tide, come back before the water rises. Learn to surf at the beginner-friendly beach break. Eat fresh seafood at the beachfront restaurants. Do a cooking class. Take a boat safari down the Mirissa lagoon.',
    best_time = 'November to April is the season. December to March is best for whales. May to October the sea gets rough and most whale trips cancel. The beach is still swimmable in the monsoon but the surf picks up and the water gets cloudy.',
    how_to_get_there = 'About 150 kilometres from Colombo — 2 hours on the expressway, 2.5 on the coastal road. Trains run from Colombo to Mirissa station (3 hours). Buses from Colombo and Galle stop at the main road junction, then a tuk-tuk to the beach.',
    suggested_itinerary = 'Three to five days is common. People come for a weekend and stay a week. Wake up, swim, eat, read, nap, surf, eat again, watch the sunset. If you need structure, add a whale trip one morning and a day trip to Galle on another.',
    where_to_stay = 'Mirissa has accommodation for every budget. The beachfront is lined with guesthouses and small hotels. Mandara Resort is mid-range with a pool. For budget, the lane behind the beach has dozens of guesthouses. Morjim by the Bay is decent mid-range. For peace, stay at the south end near the headland rather than the party end near the main strip.',
    travel_tips = 'Whale trips are most reliable in March and April. Bargain for a smaller boat; the big ones are crowded and the crew is less careful. The currents near Parrot Rock can be strong. Don''t swim there at high tide. Beer is cheaper at the shops than the beach bars.',
    nearby_travel_times = 'Weligama: 10 minutes. Matara: 20 minutes. Galle: 1 hour. Yala: 2 hours. Colombo: 2.5 hours.',
    works_well_with = 'Weligama, Galle, Yala, Hiriketiya',
    cta_text = 'Whale-watching passes that don''t treat you like cargo. We know the boats that wait for the whale, not just the clock.',
    faq_json = '[{"q":"When is the best time for whale-watching?","a":"November to April, peaking in March and April. Blue whales are spotted year-round but season is more reliable."},{"q":"Is Mirissa a party beach?","a":"It was. It still has parties but it''s more of a backpacker chill spot now."},{"q":"Can I swim at Mirissa?","a":"Yes, the bay is protected and calm for most of the year. Monsoon season has stronger currents."}]'
WHERE slug = 'mirissa'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'An east coast harbour town with the whitest sand on the island and a harbour that tells a story.',
    intro = 'Trincomalee sits on the northeast coast, a city built around one of the world''s finest natural deep-water harbours. It''s been fought over for centuries — Portuguese, Dutch, French, British, and Japanese navies all wanted it. The beach at Nilaveli, 15 minutes up the coast, is a strip of sand so white it almost hurts to look at. Uppuveli is closer to town and more developed. The war damaged Trinco badly — the city is still rebuilding. That history matters. It makes the calm water and empty beaches feel hard-won. The diving is the best in Sri Lanka.',
    why_visit = 'The beaches are genuinely world-class. Nilaveli is the best beach in Sri Lanka, full stop. The water is clear, warm, and gentle. Pigeon Island National Park is a 15-minute boat ride offshore — snorkel with reef sharks, turtles, and clouds of colourful fish. The hot springs at Kanniya are a curious stop. And the Koneswaram Temple on the cliff above the harbour is one of the oldest Hindu sites in the country. It''s quieter on this coast. You won''t queue for a sunbed.',
    things_to_do = 'Swim and sunbathe at Nilaveli or Uppuveli. Snorkel at Pigeon Island (go early before the tour boats arrive). Dive the wreck of the SS Sagaing — a WWII cargo ship 20 metres down. Visit the Koneswaram Temple. Soak in the Kanniya Hot Springs. Take a whale-watching trip (blue whales and sperm whales). Explore the old Dutch fort on the harbour.',
    best_time = 'Apr to October is the dry season on the east coast. June to September are the best months: calm seas, blue skies, no rain. November to March is the monsoon — most guesthouses close, the sea is rough, and the town shuts down. The season is short here. Plan around it.',
    how_to_get_there = 'About 260 kilometres from Colombo — 6 hours by car on the A6 highway. Trains from Colombo to Trincomalee take 7 hours. Buses run from Colombo, Kandy, and Anuradhapura. The road goes through Habarana and the Polonnaruwa junction.',
    suggested_itinerary = 'Three or four days minimum. Day one: arrive, settle in, Uppuveli beach. Day two: Pigeon Island morning, Nilaveli afternoon. Day three: diving or whale-watching, plus Koneswaram Temple. Day four: hot springs and a lazy day before heading back.',
    where_to_stay = 'Nilaveli has the best beach hotels. Anilana Nilaveli is top-end. Nilaveli Beach Resort is solid mid-range. Uppuveli has more budget options and closer to town. Trinco Blu by Cinnamon is a reliable choice. Stay in Nilaveli if you want beach, Uppuveli if you want convenience.',
    travel_tips = 'The season is strict here. Come between April and October or you''ll find empty beachfronts and closed restaurants. Pigeon Island fees are separate from the boat ride. Take reef shoes — sea urchins near the rocks. ATMs are limited in Trinco; bring cash.',
    nearby_travel_times = 'Nilaveli: 15 minutes. Uppuveli: 10 minutes. Pigeon Island: 20 minutes by boat. Polonnaruwa: 2 hours. Kandy: 5 hours.',
    works_well_with = 'Polonnaruwa, Anuradhapura, Sigiriya',
    cta_text = 'Trinco runs on a short season. Miss the window and you''re out of luck. We''ll time it right for you.',
    faq_json = '[{"q":"When does the season start in Trincomalee?","a":"April to October. The best months are June, July, August, and September."},{"q":"Is Pigeon Island worth it?","a":"Yes, but go early. By 10 AM the tour groups arrive and the water gets crowded."},{"q":"Can I see whales here?","a":"Yes. Blue whales are common from April to September."}]'
WHERE slug = 'trincomalee'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'The first great capital of Sri Lanka. A sprawling sacred city that has been a pilgrimage site for over 2,000 years.',
    intro = 'Anuradhapura is not a temple. It''s not a ruin. It''s a living city built around one of the most extensive archaeological sites in Asia. The sacred city covers 40 square kilometres — palaces, monasteries, massive stupas, and the oldest historically dated tree in the world. The Sri Maha Bodhi was grown from a cutting of the original tree under which Buddha attained enlightenment. It arrived here in 236 BC. It''s still alive. Visiting Anuradhapura is not a quick stop. You need time to absorb the scale.',
    why_visit = 'The Sri Maha Bodhi is the heart of the site. Watching pilgrims pour offerings at the tree at dawn is something you won''t forget. The stupas are enormous — Jetavanaramaya was the third tallest structure in the ancient world. You can climb the ruins of the Abhayagiri monastery. The moonstones, the guard stones, the meditation pools of the monks — the artistry is incredible. And the place is still in use. Monks walk these grounds. Devotees pray. It''s not a museum, it''s a faith.',
    things_to_do = 'Visit the Sri Maha Bodhi at dawn. Climb Jetavanaramaya and Ruwanwelisaya stupas. Explore Abhayagiri Monastery. See the Samadhi Buddha statue. Visit the Isurumuniya rock temple. Walk the museum complex. See the moonstones at the ancient palaces. Drive out to the Kuttam Pokuna (twin ponds) for the best-preserved ancient water features.',
    best_time = 'May to September is dry and hot. October to February is cooler and more comfortable for walking the site. Avoid April — the heat is punishing. If you''re coming for the full-moon pilgrimage (Poson in June), the city is crowded and electrifying.',
    how_to_get_there = 'About 200 kilometres from Colombo — 4 hours by car on the A1 and A9 highways. Trains run from Colombo to Anuradhapura (5 hours). Buses are frequent from Colombo, Kandy, and Dambulla.',
    suggested_itinerary = 'Stay one or two nights. One full day can cover the highlights if you start at 6 AM. Two days gives you time to explore the outer monasteries at leisure. Rent a bicycle to get around the sacred city — it''s the best way. The archaeological museum is worth an hour.',
    where_to_stay = 'Anuradhapura has solid mid-range hotels. Ulagalla by Uga is the luxury choice — chalets with private pools on a lake. Rajarata Hotel is decent mid-range. The Palm Garden Village is good for budget. Stay near the New Town rather than the sacred city for better food options.',
    travel_tips = 'The sacred city is huge. Don''t walk it. Rent a bicycle or hire a tuk-tuk for the day. Dress modestly — shoulders and knees covered at all sites. Shoes off at every temple. The monkeys near the temples will steal food and phones. The Bodhi tree queue is shorter before 7 AM.',
    nearby_travel_times = 'Mihintale: 30 minutes. Polonnaruwa: 1.5 hours. Dambulla: 1.5 hours. Sigiriya: 2 hours. Kandy: 4 hours.',
    works_well_with = 'Polonnaruwa, Mihintale, Dambulla, Sigiriya',
    cta_text = 'We can arrange a private guide who knows Anuradhapura''s stories — and which ruins to visit before the tour buses.',
    faq_json = '[{"q":"How much time do I need in Anuradhapura?","a":"At least one full day. Two is better if you want to see the outer sites."},{"q":"Can I wear shorts?","a":"No. Shoulders and knees must be covered at all religious sites."},{"q":"Is the Sri Maha Bodhi worth seeing?","a":"It''s a living tree from 236 BC. Yes, it''s worth seeing. Go at dawn for the atmosphere."}]'
WHERE slug = 'anuradhapura'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'A small national park known for elephants. Lots of them. Visible. Every day.',
    intro = 'Udawalawe National Park covers 308 square kilometres of open grassland and scrub forest. It was created as a reservoir catchment, which means the animals came after the dam. And they came in numbers. The elephant population is the main draw — around 500 individuals roam the park. You will see elephants here. Not maybe. You will. The park is smaller than Yala, drier, and less diverse in species. But for elephant sightings it''s the best park in Sri Lanka. The landscape is wide open, which means you can see the elephants from a distance before you approach. It''s a different experience from the dense jungle of Yala.',
    why_visit = 'The elephants. They''re not shy. You''ll see herds with calves, solitary bulls, and family groups crossing the road in front of your jeep. The Elephant Transit Home on the park boundary rehabilitates orphaned calves. You can watch the feeding sessions from a viewing platform. The birdlife is good too — eagles, storks, and the Sri Lankan junglefowl. If you came to Sri Lanka to see wild elephants, Udawalawe is the place.',
    things_to_do = 'Morning and afternoon safaris — both are good, mornings are cooler. Visit the Elephant Transit Home feeding at 9 AM, noon, and 3 PM. Birdwatch at the reservoir edge. Drive to the Udawalawe dam for the view. Visit the nearby Sankhapala Buddhist temple.',
    best_time = 'Year-round. The elephants are always present because of the reservoir. June to September is the dry season and the animals concentrate around the water sources — the best viewing. October to January is green and lush but elephants are harder to spot in the taller grass.',
    how_to_get_there = 'About 170 kilometres from Colombo — 3.5 hours by car via Ratnapura or the Southern Expressway via Embilipitiya. The park is about an hour from the A4 highway turnoff. Buses from Colombo to Wellawaya stop at the park junction.',
    suggested_itinerary = 'One night is enough. Do an afternoon safari on arrival day, a morning safari the next day, visit the Transit Home, then continue your journey. The park works well as a stopover between the hill country and the south coast or Yala.',
    where_to_stay = 'Most accommodation clusters near the park entrance. Grand Udawalawe is the premium option with a river view. Big Game Camp Udawalawe is a tented camp experience. Elephant Reach Hotel is decent mid-range. For budget, Udawalawe Safari Cottage. All the hotels arrange safaris.',
    travel_tips = 'The jeeps here are open-topped — dust is unavoidable. Bring a mask. The Elephant Transit Home feeding is free but donations help. Don''t visit during the April-May holidays when the park swarms with local tourists. Afternoon safaris often have better light for photos.',
    nearby_travel_times = 'Embilipitiya: 20 minutes. Ratnapura: 1.5 hours. Yala: 2 hours. Nuwara Eliya: 3 hours. Colombo: 3.5 hours.',
    works_well_with = 'Yala, Ratnapura, Nuwara Eliya, Sinharaja',
    cta_text = 'We can pair Udawalawe with Yala or Sinharaja for a wildlife circuit. Transfers, permits, and jeeps sorted.',
    faq_json = '[{"q":"Will I definitely see elephants?","a":"Yes. Udawalawe is the most reliable park in Sri Lanka for elephant sightings."},{"q":"How does Udawalawe compare to Yala?","a":"Fewer species but more elephants. Yala is better for leopards, Udawalawe is better for elephants."},{"q":"Can I walk in the park?","a":"No. Safaris are by jeep only. Walking is prohibited for safety."}]'
WHERE slug = 'udawalawe'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'The second ancient capital. Better preserved than Anuradhapura, more compact, and easier to explore by bicycle.',
    intro = 'Polonnaruwa took over from Anuradhapura in the 11th century as the capital of Sri Lanka. It lasted about 200 years before being abandoned. What''s left is a compact, beautifully preserved royal city. The ruins are concentrated in a few square kilometres, which makes them the easiest of the ancient capitals to explore. The Gal Vihara — four Buddhas carved from a single granite cliff — is the highlight. The statues are huge, serene, and over 800 years old. The Royal Palace once had a thousand rooms. The quadrangle packs a dozen small monuments into a single courtyard. It''s a calm place. Fewer tourists than Sigiriya, more substance than Anuradhapura.',
    why_visit = 'The Gal Vihara alone is worth the trip. The seated Buddha, the standing Buddha with crossed arms, the reclining Buddha — each is masterful. But the restored buildings are what make Polonnaruwa special. You can walk through the audience halls, examine the toilets, see the bathing pools, and understand how a medieval capital functioned. The museum is excellent. The whole place feels manageable. You can see the highlights in a morning without rushing.',
    things_to_do = 'Visit the Gal Vihara (go early to have it to yourself). Explore the Royal Palace group. Walk the quadrangle. See the Rankot Vihara stupa. Visit the Polonnaruwa Museum (one of the best in Sri Lanka). Cross the causeway over the Parakrama Samudra reservoir. Cycle through the Archaeological Park. Stop at the Lankatilaka image house.',
    best_time = 'June to September is dry but hot. January to March is cooler and more pleasant for cycling. Avoid April — extreme heat. The park is open year-round. Early morning (7 AM) is the best time to beat the heat and the crowds.',
    how_to_get_there = 'About 220 kilometres from Colombo — 4.5 hours by car on the A6 highway. Trains from Colombo to Polonnaruwa take about 6 hours. Buses run from Kandy, Dambulla, and Anuradhapura. The junction at Habarana splits north and west.',
    suggested_itinerary = 'One full day is enough. Rent a bicycle at the entrance and spend 4-5 hours touring the ruins. Start at the museum for context, then cycle anticlockwise. The afternoon is good for the Gal Vihara when the light hits the carvings. If you have two days, add a trip to Minneriya National Park for elephants.',
    where_to_stay = 'Polonnaruwa town has decent hotels. Hotel Sudu Araliya is a good mid-range option. Forest Garden Hotel is charming with a pool. Giritale Hotel is by the reservoir. For budget, the area near the new town bus station has basic guesthouses. The ruins are best approached from the south side.',
    travel_tips = 'Rent a bicycle at the entrance, not in town. The park roads are flat and easy. The museum has good air conditioning and excellent exhibits. Take water and a hat. Monkeys at the site will grab unattended bags. The ticket also covers the museum and the Gal Vihara.',
    nearby_travel_times = 'Minneriya: 30 minutes. Dambulla: 1 hour. Sigiriya: 1 hour. Anuradhapura: 1.5 hours. Kandy: 3 hours.',
    works_well_with = 'Sigiriya, Dambulla, Anuradhapura, Minneriya',
    cta_text = 'We can arrange a cycling tour of Polonnaruwa with a local archaeologist. Better than renting a bike and a map.',
    faq_json = '[{"q":"How long do I need at Polonnaruwa?","a":"Half a day covers the main sites. A full day is plenty."},{"q":"Is cycling the best way to explore?","a":"Yes. The park is flat, compact, and bike-friendly. Tuk-tuks also available."},{"q":"What''s the Gal Vihara?","a":"Four massive Buddha statues carved from a single granite cliff face. Over 800 years old."}]'
WHERE slug = 'polonnaruwa'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'A crescent bay on the east coast that became a surfer''s paradise. The waves here are legendary.',
    intro = 'Arugam Bay is a small fishing village on the southeast coast that got turned into a surfing mecca. The main wave — A-Bay or the Point — is a long right-hand break that peels for 200 metres. It''s one of the best surf waves in Asia. The village runs on surf time. People wake up at 5 AM to check the swell, surf for three hours, sleep through the afternoon, surf again in the evening. The town is dusty, scruffy, and utterly charming. It''s less commercial than the south coast. More raw. The road in is rough and the power cuts are frequent. Nobody comes here for luxury. They come for the wave.',
    why_visit = 'The surf is the reason. Intermediate and advanced surfers know this wave. But there''s more than the Point. Beginners can learn at Pottuvil Point or the beach break in front of the Stardust Cafe. The lagoon is good for SUP. The national parks nearby — Kumana and Lahugala — are excellent for wildlife and basically empty. During the season the town has a festival atmosphere. Full moon parties, barbecues on the beach, and a crowd that''s more surfer than backpacker.',
    things_to_do = 'Surf the Point (respect the locals and don''t drop in). Take a surf lesson at Whiskey Point. Visit the Elephant Rock viewpoint. Go on a safari to Kumana National Park. Explore the Mangrove Lagoon by kayak. Visit the Muhudu Maha Viharaya ruins on the beach. Watch sunset from the A-Bay surf spot. Eat seafood at the Ranga Restaurant.',
    best_time = 'May to September is the east coast surf season. June and July are the best months — consistent swell, offshore winds. October and November bring the monsoon and the town shuts down. The surf in May is smaller but the crowds are thinner.',
    how_to_get_there = 'About 320 kilometres from Colombo — 6 hours by car via the A4 highway through Monaragala. The road from Monaragala to Arugam Bay is winding and slow. Buses run from Colombo to Pottuvil, then a tuk-tuk the last 5 kilometres. Alternatively, fly to Batticaloa or Hambantota and drive from there.',
    suggested_itinerary = 'A week is standard. Surfers typically stay for two. The daily rhythm is: dawn surf, breakfast, hammock, lunch, nap, afternoon surf, dinner, bed. If you need breaks, add a day trip to Kumana or the lagoon. The east coast in season is the most relaxed place in Sri Lanka.',
    where_to_stay = 'Accommodation is casual. Hideaway Hotel is a classic surfer guesthouse. Ocean View has sea views and a pool. Stardust Hotel is popular. A Bay Breeze is mid-range and comfortable. Most places are basic — hot water, slow Wi-Fi, ceiling fan. That''s the vibe. Book ahead for peak months.',
    travel_tips = 'The surf is not for beginners at the Point. Learn at Whiskey Point first. The power cuts are regular — charge everything when you can. The mosquitoes at dusk are savage. Bring DEET. The road from Pottuvil is unsealed and full of potholes. The atmosphere in Arugam Bay is laissez-faire. Don''t expect 5-star service and you''ll love it.',
    nearby_travel_times = 'Pottuvil: 5 minutes. Kumana National Park: 30 minutes. Lahugala: 30 minutes. Batticaloa: 2 hours. Yala: 3 hours.',
    works_well_with = 'Yala, Udawalawe, Ella (via Passara Road), Batticaloa',
    cta_text = 'We can set you up with board hire, accommodation near the Point, and a driver who knows the back roads from Ella.',
    faq_json = '[{"q":"Is Arugam Bay only for experienced surfers?","a":"No. The Point is for intermediate/advanced but Whiskey Point is great for beginners."},{"q":"How do I get to Arugam Bay?","a":"Road from Colombo (6 hours), bus to Pottuvil, or fly to Batticaloa and drive (2 hours)."},{"q":"Is the village safe?","a":"Very. It''s one of the safest places in Sri Lanka. The main risks are petty theft on the beach."}]'
WHERE slug = 'arugam-bay'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'A resort town on the west coast where the beach is wide, the sea is calm, and the tourists are mostly package holiday.',
    intro = 'Bentota is a long strip of sand between the Bentota River and the Indian Ocean, about 65 kilometres south of Colombo. It''s the classic Sri Lankan beach resort: wide golden beach, calm water, rows of sunbeds under umbrellas. The hotels here are big — large resorts with pools, buffets, and tour desks. It''s not adventurous. It''s comfortable. The Bentota River adds some variety: you can take a boat safari through the mangroves, see monitor lizards and water monitors, and visit the Brief Garden by Bevis Bawa. But the main event is the beach. If you want to lie on sand and do nothing for a week, Bentota delivers.',
    why_visit = 'The beach is the best on the west coast — wider and cleaner than Negombo, calmer than Hikkaduwa. The river safari is genuinely good for wildlife spotting. The turtle hatchery at nearby Kosgoda is a worthwhile stop. And it''s close enough to Colombo for a quick getaway. The downside is the resort cocoon — you can eat, sleep, and swim without ever meeting a Sri Lankan outside the hotel staff. Make an effort to explore beyond the resort gates.',
    things_to_do = 'Swim and sunbathe on the main beach. Take a boat safari on the Bentota River. Visit Brief Garden. Visit the Kosgoda Turtle Hatchery. Try water sports — jet skiing, windsurfing, banana boats. Walk along the beach at low tide to the rocky headland at the north end. Eat at a local restaurant outside the hotel zone. Take a day trip to Galle or Hikkaduwa.',
    best_time = 'November to April is the dry season on the west coast. December to March is perfect beach weather. May to July gets rain and rough seas. August to October is mixed. The resorts run year-round but the beach is best in the northern winter.',
    how_to_get_there = '65 kilometres from Colombo on the Southern Expressway — about 45 minutes. The coastal road (A2) takes an hour. Trains from Colombo to Bentota run hourly — about 1.5 hours. The station is in Aluthgama, a short tuk-tuk from the beach.',
    suggested_itinerary = 'Two to four days is the sweet spot. Longer if you just want a beach holiday. Day one: arrive, settle in, swim. Day two: river safari in the morning, beach afternoon. Day three: day trip to Galle or a turtle hatchery visit. Day four: lazy morning and head back.',
    where_to_stay = 'Bentota is dominated by big hotels. The Taj Bentota is the best — a sprawling property on a private beach. Club Bentota is mid-range and reliable. For budget, the smaller guesthouses in Aluthgama or along the beach road. Villa Bentota is boutique and lovely but expensive. The resorts all have good pools.',
    travel_tips = 'The beach is public — hawkers will approach. A polite "no" works. The river safari price is negotiable. The sea here is safe for swimming most of the year. The resort buffets are convenient but the local restaurants in Aluthgama are better and cheaper.',
    nearby_travel_times = 'Aluthgama: 5 minutes. Kosgoda: 15 minutes. Hikkaduwa: 30 minutes. Galle: 45 minutes. Colombo: 45 minutes.',
    works_well_with = 'Galle, Hikkaduwa, Colombo, Kosgoda',
    cta_text = 'We can book a Bentota resort with a river view rather than a carpark view. Beach time, planned.',
    faq_json = '[{"q":"Is Bentota good for swimming?","a":"Yes. The sea is calm and safe most of the year. Lifeguards patrol the main beach."},{"q":"Is Bentota better than Hikkaduwa?","a":"For swimming, yes. For surfing or nightlife, Hikkaduwa wins."},{"q":"Can I take a day trip from Bentota?","a":"Easily. Galle, Hikkaduwa, and Colombo are all within an hour."}]'
WHERE slug = 'bentota'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'Sri Lanka''s original surf beach. A scruffy, lively strip where the waves break hard and the nightlife is loud.',
    intro = 'Hikkaduwa was the first place on the south coast to attract tourists. It started with surfers in the 1970s and grew from there. The main strip is a chaotic mix of guesthouses, restaurants, dive shops, and bars playing reggae at ear-level volume. The coral sanctuary just offshore is good for snorkelling. The surf breaks are consistent and challenging. It''s not pretty the way Mirissa is pretty. It''s scruffy. But it has energy. Hikkaduwa wears its age well. The crowd is a mix of first-time package tourists and old-timers who''ve been coming since the 1980s.',
    why_visit = 'The coral reef is the biggest draw — you can snorkel right off the beach. The nightlife is the liveliest on the south coast. The turtle watching is reliable: the beach is a nesting site, and hatchlings make their way to the sea most nights in season. The shop scene is better than average, and the Sunday market is actually worth visiting. But mostly you come to Hikkaduwa because it''s alive. Other south coast beaches are for relaxing. Hikkaduwa is for doing things.',
    things_to_do = 'Snorkel at the Coral Sanctuary (the marine park with glass-bottom boats). Surf at the main break or Benny''s. Take a diving course — several PADI centres operate here. Go turtle watching at the beach or visit the turtle hatchery. Visit the Tsunami Photo Museum. Eat at the Sunday Beach Market. Drink at the bars along the main strip. Take a boat to the coral garden.',
    best_time = 'November to April is the season. December to March is peak. May to October brings monsoon swell, rough seas, and fewer tourists. The surf is better in the off-season for experienced surfers. The coral is most visible in calm months.',
    how_to_get_there = '98 kilometres from Colombo — 1.5 hours by car on the coastal road, 1 hour on the expressway. Trains from Colombo to Hikkaduwa take about 2 hours and are very scenic. The railway line runs right along the coast near the station.',
    suggested_itinerary = 'Two to three nights. Day one: arrive, snorkel, explore the strip. Day two: diving or surf lesson, afternoon turtle watching, evening at the bars. Day three: morning at the market or a final swim, then onward to Galle or back to Colombo.',
    where_to_stay = 'The strip is lined with hotels. The Blue Note is stylish mid-range. Hikka Tranz by Cinnamon is the big resort. White Villa is a good budget option. For peace, stay north of the town centre. The railway side is noisy; ask for a room on the beach side.',
    travel_tips = 'The railway line runs parallel to the beach. Trains are frequent and the horn is loud. Check train timetables before walking on the tracks. The coral sanctuary has an entrance fee and fines for touching the coral. The currents can be strong outside the protected area. The main road is dangerous after dark — tuk-tuks with no lights are common.',
    nearby_travel_times = 'Galle: 30 minutes. Bentota: 30 minutes. Unawatuna: 40 minutes. Colombo: 1.5 hours.',
    works_well_with = 'Galle, Unawatuna, Bentota',
    cta_text = 'We can set up a snorkel trip to the coral sanctuary with a proper guide — not a glass-bottom boat that blocks the view.',
    faq_json = '[{"q":"Is Hikkaduwa good for beginners to surf?","a":"The main break is better for intermediate. Beginners should try the north end of the beach."},{"q":"Is the coral reef accessible from the shore?","a":"Yes. You can snorkel from the beach at the Coral Sanctuary area."},{"q":"Is Hikkaduwa safe at night?","a":"The main strip is safe and busy. Stick to well-lit areas and watch your drink."}]'
WHERE slug = 'hikkaduwa'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'The northern capital. Tamil culture, civil war history, and the best seafood in Sri Lanka.',
    intro = 'Jaffna feels different from the rest of Sri Lanka. The language is Tamil. The architecture is Hindu. The landscape is flat and dry, covered in palmyra palms. The civil war devastated this city and the wounds aren''t buried deep. But the recovery is real. New restaurants open every month. The market is busy. The old library — burned in 1981 with a collection of priceless Tamil manuscripts — has been rebuilt. The food is extraordinary. The history is heavy. The people are warm. Jaffna is not an easy trip. It''s a long drive from anywhere. But it''s the most distinctive city in Sri Lanka.',
    why_visit = 'The Nallur Kandaswamy temple is one of the most impressive Hindu temples in the country — gopurams covered in carvings, festivals that spill into the streets. The Jaffna Fort is a massive star-shaped Dutch fort that''s still being restored. The islands off the coast — Kayts, Karainagar, and the remote Delft — offer beaches that feel like another world. The cuisine is unique: crab curry, odiyal (a kind of beef stew), and dosas that ruin you for dosas anywhere else.',
    things_to_do = 'Visit Nallur Kandaswamy Temple (go during puja for the full experience). Explore Jaffna Fort. Walk the Jaffna public market. Take a ferry to the islands — Kayts is closest, Delft is a full-day trip. Visit the Jaffna Library. Eat seafood at Mango or Rio''s Beach. Drive up to Point Pedro, the northernmost point of Sri Lanka. Visit the ruined Buddhist temples at Nagadeepa.',
    best_time = 'January to April is the dry season. February and March are the best months. June to September is hot and dry but fine. October to December gets the monsoon — roads flood and the islands can be inaccessible.',
    how_to_get_there = 'About 400 kilometres from Colombo — 7 hours by car on the A9 highway. The highway was rebuilt after the war and is now good. Trains run from Colombo to Jaffna (7 hours overnight or about 8 hours daytime). Flights from Colombo to Jaffna take 45 minutes (Air Senok or Cinnamon Air).',
    suggested_itinerary = 'Three nights minimum. Day one: arrive, explore the fort and market. Day two: Nallur temple, ferry to Kayts or Delft. Day three: Point Pedro, the library, a cooking class. The islands need a full day.',
    where_to_stay = 'Jaffna has improved massively. Jetwing Jaffna is the best hotel — modern, comfortable, with a pool. Fox Jaffna is boutique and beautiful. The Jaffna Heritage Hotel is mid-range. For budget, the area near the market has guesthouses. The islands have very limited accommodation.',
    travel_tips = 'The security checkpoints are still present but routine. Carry your passport. The best food is in the market and the small family-run restaurants, not the tourist spots. The sun is brutal — bring a hat. The islands have limited facilities; take water and snacks. Credit cards are accepted in hotels but cash rules the market.',
    nearby_travel_times = 'Nallur: 10 minutes. Kayts: 30 minutes by ferry. Delft: 1.5 hours by ferry. Point Pedro: 1 hour. Mannar: 3 hours.',
    works_well_with = 'Mannar, Anuradhapura, Negombo (on the way south)',
    cta_text = 'Jaffna needs planning — permits for some sites, ferry schedules, guides who speak Tamil. We can sort it.',
    faq_json = '[{"q":"Is Jaffna safe to visit?","a":"Yes. The war ended in 2009. The city is peaceful and welcoming."},{"q":"Do I need a special permit for Jaffna?","a":"No. The former military permits are no longer required for tourists."},{"q":"What is Jaffna famous for?","a":"Tamil culture, Hindu temples, the rebuilt library, and the best seafood in Sri Lanka."}]'
WHERE slug = 'jaffna'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'A beach town near Colombo that everyone passes through. The lagoons and the fish market make it worth a stop.',
    intro = 'Negombo is the first place most tourists see after clearing customs at Colombo airport. It''s 15 minutes from the terminal — close enough that the hotel pickup includes a "welcome to Sri Lanka" and a traffic jam in the same breath. The town has a large lagoon, a lively fish market, and a beach that''s okay but not stunning. The Dutch canal is a remnant of the colonial era. The Catholic churches multiply like tuk-tuks. Negombo is more functional than beautiful. But it has a real Sri Lankan town character that the resort strips lack.',
    why_visit = 'Convenience is the main reason. Arrive off a late flight, collapse into a Negombo hotel, and start your trip fresh the next morning. But if you give it a day, the fish market at dawn is spectacular — the catch comes in before sunrise and the auction is chaos. The lagoon boat ride is quiet and the birdlife is good. The fishing nets on stilts make good photos. And the seafood in Negombo is cheap and fresh.',
    things_to_do = 'Visit the Negombo fish market at dawn. Take a boat ride on the lagoon. Walk the Dutch canal. Visit the St. Mary''s Church. Eat seafood at a beachside restaurant. Buy cinnamon and spices at the town market. Watch the fishermen on stilts. Relax at a beach bar for sunset.',
    best_time = 'Year-round. Negombo works as a stopover any time. December to April has the best beach weather. May to August brings rain but the lagoon tours still run. It doesn''t matter when your flight lands — Negombo is here.',
    how_to_get_there = '7 kilometres from Bandaranaike International Airport — 15 minutes by car. 40 minutes from Colombo. Trains run from Negombo to Colombo Fort every hour. The bus from the airport to Negombo town is cheap and frequent.',
    suggested_itinerary = 'One night is standard. Arrive, eat, sleep, leave. If you stay longer, the fish market one morning and a lagoon tour the next day fills the time nicely. Some people use Negombo as a base for day trips to Colombo or the west coast.',
    where_to_stay = 'The beach strip north of town has the best hotels. Jetwing Beach is the top choice. The Gateway Hotel by Taj is grand. For budget, the guesthouses near the beach or the town centre. Silver Sands is reliable mid-range. Near the airport, the Jetwing Lagoon or the Wallawwa are excellent for early flights.',
    travel_tips = 'The airport has no exit tax but the shops inside are expensive. The fish market smells strong — morning is the time to go. The water in the Negombo lagoon is not clean enough for swimming. Beach hawkers are persistent but polite. The canal walk is most atmospheric in the late afternoon.',
    nearby_travel_times = 'Airport: 15 minutes. Colombo: 40 minutes. Galle: 1.5 hours. Chilaw: 1 hour.',
    works_well_with = 'Colombo, Chilaw, Kalpitiya',
    cta_text = 'We can recommend a Negombo hotel that''s close enough to the airport but far enough from the flight path. Grab dinner, sleep, then we move.',
    faq_json = '[{"q":"Should I stay in Negombo or Colombo?","a":"For the first night, Negombo wins — it''s closer to the airport and more relaxed."},{"q":"Is the Negombo beach swimmable?","a":"It''s okay but the lagoon mouth makes the water murky. Better beaches are an hour south."},{"q":"Is the fish market worth waking up for?","a":"Yes. The auction starts around 5 AM. It''s chaotic, photogenic, and the seafood is fresh."}]'
WHERE slug = 'negombo'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'The cave temple that stops everyone on the way north. Five caves, 153 Buddha statues, and a golden Buddha visible from the highway.',
    intro = 'Dambulla is a town that exists because of a rock. The rock is 160 metres high and riddled with caves. Inside those caves is a temple complex that has been active for 22 centuries. The five main caves are packed with Buddha statues — standing, sitting, lying down — 153 in total. The murals on the ceilings and walls cover 2,100 square metres. The golden Buddha statue at the base is 30 metres tall and visible from the main road. Dambulla is a quick stop, not a destination. But it''s an essential one. You can''t understand Sri Lankan Buddhism without walking through these caves.',
    why_visit = 'The scale of the complex is the first surprise. Cave 1 has a 14-metre reclining Buddha. Cave 2 is the largest — 52 metres wide, with 56 statues and a dagoba in the centre. The ceilings are painted with scenes from the Buddha''s life, all in good condition. The view from the entrance platform stretches across the plains to Sigiriya. And it''s all still in use. Monks live here. Pilgrims come. It''s not a dead monument.',
    things_to_do = 'Climb the stairs to the cave temple (1.2 kilometres, gentle slope). Explore all five caves slowly. Visit the New Golden Temple at the base — less historic but visually striking. Walk to the Dambulla museum. Look at the view of Sigiriya in the distance. Visit the local market for fruits and vegetables.',
    best_time = 'Year-round but mornings are essential — the caves get hot and crowded by 11 AM. January to April is the best weather. The site is covered, so rain doesn''t matter much but the stairs get slippery.',
    how_to_get_there = '148 kilometres from Colombo — 4 hours by car on the A1 highway to Dambulla junction. Buses run from Colombo, Kandy, and Anuradhapura. The town is at the intersection of the A6 and A9 highways, impossible to miss.',
    suggested_itinerary = 'Two hours at the caves is enough. Most people stop en route to Sigiriya or Anuradhapura. If you''re staying overnight, the town itself is functional but not charming. The nearby Rose Quartz Mountain and the Iron Wood Forest are minor attractions for die-hard explorers.',
    where_to_stay = 'Dambulla is a transit town with decent hotels. Amaya Lake is a good mid-range option with a pool. Kalundewa Retreat is boutique and quiet. For budget, the guesthouses around the junction. Most travellers stay near Sigiriya and visit Dambulla on the way.',
    travel_tips = 'The stairs are steep for the last 100 metres. Take it slow. The shoe deposit at the entrance is a scam — the attendant asks for a "donation" that''s not optional. Leave shoes with a vendor if you''re worried. The golden Buddha at the base is a modern addition, not ancient. The market has excellent fruit.',
    nearby_travel_times = 'Sigiriya: 20 minutes. Polonnaruwa: 1 hour. Anuradhapura: 1.5 hours. Kandy: 2 hours. Colombo: 4 hours.',
    works_well_with = 'Sigiriya, Polonnaruwa, Anuradhapura, Kandy',
    cta_text = 'We route the Dambulla stop so you hit the caves before the tour buses arrive. 8 AM entry, no queues.',
    faq_json = '[{"q":"Is Dambulla worth a separate trip?","a":"It''s better as a stopover between Kandy and Sigiriya or Anuradhapura. Half a day is enough."},{"q":"How many steps to the caves?","a":"About 300 steps. The walkway is covered but still a climb."},{"q":"Can I take photos inside the caves?","a":"Yes. Photography is allowed. No flash inside the main shrine rooms."}]'
WHERE slug = 'dambulla'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'A windswept plateau at 2,100 metres where the walking trail ends at the edge of the world.',
    intro = 'Horton Plains is not a pretty park. It''s a cold, misty, exposed plateau that sits at 2,100 metres above sea level. And it''s magnificent. The main walk is a 9.5-kilometre loop that takes you across open grassland, through cloud forest, and finally to World''s End — a cliff that drops 880 metres straight down. On a clear day you can see the south coast. On a misty day you can''t see your hand in front of your face. Both versions are memorable. The park is home to sambar deer, purple-faced langurs, and the elusive Sri Lankan leopard. Birders come for the endemic species. The atmosphere is like nowhere else in Sri Lanka.',
    why_visit = 'World''s End is the obvious reason. There''s nothing like standing at a precipice that goes from 2,100 metres to sea level without warning. But the walk itself is worth it. The trail is flat and easy — a boardwalk through the wettest part, gravel paths through the rest. Baker''s Falls is a pleasant 20-metre waterfall. The cloud forest at the edge of the grassland is dense, dark, and full of wildlife. The silence on the plateau is absolute. Then the wind picks up.',
    things_to_do = 'Walk the full loop (2.5 to 3 hours). Take the side trail to Baker''s Falls. Birdwatch for the Sri Lankan blue magpie and the yellow-eared bulbul. Have a picnic at the viewpoint near World''s End. Visit Farr Inn, a colonial-era hunting lodge that''s now a museum. Photograph the mist rolling over the escarpment.',
    best_time = 'January to April is the dry season — the only time World''s End is reliably clear. The mist usually clears by midday or it doesn''t clear at all. You need to arrive by 6 AM to have a chance at the view. May to December is mostly cloud. The park is open year-round but you''ll be walking in cloud most days.',
    how_to_get_there = 'About 180 kilometres from Colombo — 4 hours by car through Nuwara Eliya and Ambewela. The last 10 kilometres are a rough road through tea plantations. You''ll need your own transport (or a tour) — public transport doesn''t reach the park. From Nuwara Eliya it''s about an hour.',
    suggested_itinerary = 'Half a day. Start from Nuwara Eliya at 5 AM, arrive at the park by 6, walk the loop, and be back in Nuwara Eliya for lunch. It''s a morning trip. There''s no accommodation inside the park.',
    where_to_stay = 'Accommodation is in Nuwara Eliya or Ohiya. Stay in Nuwara Eliya for the convenience. Jetwing Warwick Gardens or the Grand Hotel. For early starts, the guesthouses near the Horton Plains entrance at Ohiya are basic but save you the morning drive.',
    travel_tips = 'Warm clothes are non-negotiable. It''s 10°C at 6 AM at altitude. The trail is muddy after rain. The wind at World''s End is strong — don''t lean too far. Entry is strictly timed between 6 AM and 10 AM. After 10 AM they stop issuing tickets. The park permits must be booked in advance through the Department of Wildlife Conservation.',
    nearby_travel_times = 'Nuwara Eliya: 1 hour. Ohiya: 15 minutes. Haputale: 1.5 hours. Ella: 2 hours. Colombo: 4 hours.',
    works_well_with = 'Nuwara Eliya, Ella, Haputale',
    cta_text = 'We handle the permit, the early-morning driver, and the thermos of tea. You just walk to the edge.',
    faq_json = '[{"q":"Is the walk difficult?","a":"No. It''s 9.5 kilometres on flat, well-maintained paths. Suitable for most fitness levels."},{"q":"Do I need a guide?","a":"No. The trail is a loop and well-marked. A guide adds birding expertise."},{"q":"What if it''s cloudy?","a":"World''s End might be obscured. The walk and the cloud forest atmosphere are still worth it."}]'
WHERE slug = 'horton-plains'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'A mountain range that looks like a clenched fist from above. Misty peaks, dense jungle, and trails nobody walks.',
    intro = 'The Knuckles Mountain Range gets its name from the way the peaks resemble a clenched fist. It''s a Unesco World Heritage site, a biodiversity hotspot, and one of the least visited parts of the central highlands. The trails here are tough — slippery, steep, and remote. You''re not hiking for an Instagram photo. You''re hiking because you want to walk through a forest that hasn''t changed in thousands of years. The endemic species list is staggering. The villages at the edge of the range are tea and spice farming communities that see very few tourists. It''s a proper adventure.',
    why_visit = 'The hiking is the point. The Knuckles range has some of the best trekking in Sri Lanka — multi-day trails through cloud forest, past waterfalls, and into valleys where the only sounds are birds and running water. The biodiversity is extraordinary. Dwarf elephants once lived here. Today you''ll find endemic frogs, lizards, and birds. The views from the peaks are huge — this is the backbone of the island. And the villages at the base — Meemure, Kottegoda — are a window into traditional Sri Lankan hill-country life.',
    things_to_do = 'Hike the Knuckles summit (a tough day hike, start at 5 AM). Do the multi-day Meemure trek (2-3 days, require a guide). Visit the village of Meemure at the base. Explore the Bambarakiri Ella waterfall. Birdwatch in the cloud forest. Stay in a village homestay. Photograph the mist in the valleys at dawn.',
    best_time = 'January to April is the dry season. Trails are safer, the views are clearer, and you won''t be walking through mud. May to August brings heavy rain — trails are slippery and leeches are abundant. September to December is mixed. The best time to visit is February and March.',
    how_to_get_there = 'About 30 kilometres from Kandy, but the road is slow and winding. From Kandy, drive to Thelgamuwa or Moragahamula, then hike in. A 4WD is essential for the approach roads. Public transport goes to the edge of the range; from there you walk. You''ll need a guide for most trails.',
    suggested_itinerary = 'A minimum of two days overnight. Day one: drive from Kandy, hike to a village or campsite. Day two: summit hike or deeper valley trek. Return to Kandy by evening. A longer 3-4 day trek takes you through multiple villages and up several peaks.',
    where_to_stay = 'Basic village homestays in Meemure and Kottegoda. No hotels, no resorts. The homestays are simple — a room, a mat, a meal cooked on a wood fire. Camping is possible. For a comfortable base, stay in Hunas Falls or Thelgamuwa at the edge of the range.',
    travel_tips = 'A guide is not optional for multi-day treks. The trails are unmarked and the forest is dense. Leeches are a fact of life — wear leech socks and don''t take it personally. The water is safe from mountain streams but treat it anyway. The villages have no electricity or mobile reception in the deeper sections. You''re genuinely off the grid here.',
    nearby_travel_times = 'Kandy: 1.5 hours to the trailhead. Thelgamuwa: 30 minutes. Hunas Falls: 20 minutes. Colombo: 4 hours.',
    works_well_with = 'Kandy, Matale, Dambulla',
    cta_text = 'Knuckles is serious hiking. We can connect you with a local guide who actually knows the trails — not the guy who takes tourists to the same waterfall every day.',
    faq_json = '[{"q":"Do I need to be fit for Knuckles?","a":"Yes. The hikes are steep, the terrain is uneven, and the altitude adds challenge."},{"q":"Are there leeches?","a":"Yes. Especially in the wet season. Wear leech socks and accept it as part of the experience."},{"q":"Can I visit Knuckles in one day?","a":"You can do a day hike but the range rewards multi-day trips. Two days minimum recommended."}]'
WHERE slug = 'knuckles-mountain-range'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'A small beach cove that''s basically a resort strip now. Good sand, calm water, and restaurants that slide into the sea.',
    intro = 'Unawatuna is a classic bay beach 10 minutes from Galle. The sand is a golden crescent. The water is calm enough for toddlers. The reef keeps the swell out. It''s the most convenient beach on the south coast if you''re based in Galle. And it shows — the bay is lined with sunbeds, restaurants, and guesthouses that have been operating since the 1990s. It''s developed. During season, the beach is busy. There''s a party scene on the north end that can get loud. But the bay is lovely, the swimming is safe, and the seafood is good.',
    why_visit = 'It''s right next to Galle. If you''re spending time in the Fort and you want a beach day, this is where you go. The reef is decent for snorkelling — a short swim out. The Japanese Peace Pagoda on the headland between Unawatuna and Galle is a pleasant walk. The vibe is low-effort. You don''t plan much in Unawatuna. You swim, you eat, you drink, you leave.',
    things_to_do = 'Swim at the main beach. Snorkel the reef at the western end. Walk up to the Japanese Peace Pagoda. Get a massage on the beach (yes, it''s touristy, no, it''s not that good). Eat dinner at the beachfront restaurants. Walk to Jungle Beach on the other side of the headland. Party at the full moon event if it''s on.',
    best_time = 'November to April is the season. December to March is peak. May to October the beach is emptier but the sea can be rough. The reef protects the immediate bay so it''s swimmable most of the year.',
    how_to_get_there = '5 kilometres from Galle — 10 minutes by tuk-tuk. Trains from Colombo run to Galle, then a tuk-tuk. Buses from Colombo and Galle stop at the main road junction, then a short walk or ride.',
    suggested_itinerary = 'One or two nights is enough unless you''re using it as a beach base. Day one: arrive, beach, sunset at the Pagoda. Day two: swim, lazy lunch, afternoon walk to Jungle Beach. That works.',
    where_to_stay = 'The beachfront has dozens of options. Cantaloupe Levels is boutique and nice. The Thambili is mid-range with a pool. For budget, the lane behind the beach. Stay at the south end for quiet, north end for party.',
    travel_tips = 'The beach is public — sunbed renters will find you. The restaurants on the beach serve decent food at a markup over the road. Jungle Beach is small and gets packed. The turtles that congregate near the reef are not there every day.',
    nearby_travel_times = 'Galle: 10 minutes. Jungle Beach: 15-minute walk. Hikkaduwa: 30 minutes. Mirissa: 40 minutes. Colombo: 1.5 hours.',
    works_well_with = 'Galle, Hikkaduwa, Mirissa',
    cta_text = 'We''ll set you up with a room that has sea views, not street views. Unawatuna is better when you''re two rows back.',
    faq_json = '[{"q":"Is Unawatuna safe for swimming?","a":"Yes. The bay is protected by a reef. Calm water year-round."},{"q":"Is Unawatuna good for snorkelling?","a":"Decent. The reef is accessible from the beach. Better options at Hikkaduwa or Pigeon Island."},{"q":"How far is Unawatuna from Galle?","a":"10 minutes by tuk-tuk. You can walk along the coast path in about 30 minutes."}]'
WHERE slug = 'unawatuna'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'A shallow bay that''s the best learning ground for surfers in Sri Lanka. Flat water, mellow waves, and a scene built around beginners.',
    intro = 'Weligama means sandy village and the name fits. The bay is a long, shallow curve of sand with a reef break at the east end and a beach break along the whole shore. It''s the best place in Sri Lanka to learn how to surf. The waves are small, consistent, and forgiving. Every second building is a surf school. Boards and instructors are cheap. The town itself is spread along the coastal road — guesthouses, cafes, and the occasional gem shop. It''s not as pretty as Mirissa but it''s more functional. Everyone''s here to surf or to teach surfing.',
    why_visit = 'The surf learning conditions are as good as it gets. The bay is sheltered, the water is warm, and the waves break evenly. You can go from never surfed to standing up in one session. The vibe is relentlessly positive — beginners fall off, laugh, and get back on. The instructors are patient. The board rental is 1,000-1,500 LKR for an hour. If you''ve ever wanted to surf, this is where you do it.',
    things_to_do = 'Take surf lessons (book a few sessions over a few days). Rent a board and practice. Walk east along the beach to the No. 2 surf break (for intermediates). Visit the Weligama Marriott for a drink if you want a change of scene. Take a day trip to Mirissa or Galle. Watch the sunset from the beach. Eat at the Twin Coconut restaurant.',
    best_time = 'November to April is the surf season. December to March has the best combination of swell and flat water. May to October the monsoon brings bigger swell and rough conditions. Beginners should aim for the season.',
    how_to_get_there = '145 kilometres from Colombo — 2 hours on the expressway. Trains from Colombo to Weligama take about 2.5 hours. The station is a short walk from the beach. Buses from Colombo and Galle stop on the main road.',
    suggested_itinerary = 'Three to five days for a proper surf camp. Structure: surf in the morning, rest in the afternoon, surf again at sunset. The days blur together in a good way. If you''re not surfing, two nights is enough.',
    where_to_stay = 'Weligama has accommodation spreading along the coast. Weligama Bay Resort is a good mid-range option. Marriott Weligama is the luxury end. For budget, the guesthouses along the beach road. Book something with a pool — after a morning of paddling you''ll want to float.',
    travel_tips = 'The board rental price includes the instructor if you ask. Don''t pay for a session without confirming who''s teaching. The reef cut situation is real — reef booties are worth buying. The tide affects the waves; check the surf report before you pay for a session. The beach gets a bit of rubbish in the afternoon.',
    nearby_travel_times = 'Mirissa: 10 minutes. Matara: 15 minutes. Galle: 40 minutes. Hiriketiya: 20 minutes. Colombo: 2 hours.',
    works_well_with = 'Mirissa, Hiriketiya, Galle, Matara',
    cta_text = 'We can set up a multi-day surf camp package — accommodation, boards, and a coach who won''t just push you into a wave and yell.',
    faq_json = '[{"q":"Is Weligama good for beginner surfers?","a":"The best in Sri Lanka. Small, consistent waves and lots of instructors."},{"q":"How much do surf lessons cost?","a":"Around 2,000-3,000 LKR for a 1.5-hour lesson including board hire."},{"q":"Can more advanced surfers enjoy Weligama?","a":"The main break is for beginners. Experienced surfers should try No. 2 break or walk to Hiriketiya."}]'
WHERE slug = 'weligama'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'A quiet south coast town with a huge beach and nothing much to do. That''s the point.',
    intro = 'Tangalle is the last major town on the south coast before the road turns inland towards Hambantota. The beach here is enormous — kilometres of sand with barely a soul on it. It''s not a resort strip. There are a few guesthouses, a handful of restaurants, and a lot of empty coastline. That''s exactly why people come. Tangalle is for the traveller who wants to sit on a near-empty beach and read a book for four days. The town itself is sleepy. The beach is the attraction. If you want beach bars, jet skis, and DJs, stay in Mirissa. If you want peace, come here.',
    why_visit = 'The emptiness of the beaches. Goyambokka, Silent Beach, and Pallikaduwa are all within a few kilometres and each feels like a private cove. The sea is a deeper blue here than on the west coast. The water quality is excellent. The Rock Lookout at the eastern end of the bay is a lovely short walk. The Rekawa Turtle Sanctuary nearby is one of the best places in Sri Lanka to see turtles nesting at night.',
    things_to_do = 'Do nothing on the beach. Walk the length of Goyambokka. Visit the Rekawa Turtle Sanctuary (night visits, guide required). Eat at the beachfront seafood restaurants. Walk to the Tangalle Rock Lookout. Take a day trip to Mulkirigala Rock Temple — cave frescoes and a good view, and almost nobody goes there. Spot crocodiles at the Tangalle Lagoon.',
    best_time = 'December to April is the dry season. January to March is perfect. May to August the swell picks up and swimming is less safe. September to November is mixed. The turtle nesting season runs year-round with a peak from June to September.',
    how_to_get_there = 'About 195 kilometres from Colombo — 2.5 hours on the Southern Expressway to the Beliatta exit, then 20 minutes to Tangalle. Buses run from Colombo and Galle. The nearest train station is Matara, about 1 hour away.',
    suggested_itinerary = 'Two to four nights. The longer you stay, the more you slow down. Do a turtle visit one night, a day trip to the Rock Temple another day. The rest is beach time. There''s not much else to do and that''s the arrangement.',
    where_to_stay = 'Tangalle has some of the best boutique hotels in Sri Lanka. Anantara Peace Haven is luxury on a private beach. Bengal Bay is mid-range with a lovely setting. For budget, the guesthouses near Goyambokka Beach. Tangalle Beach Resort is a solid choice.',
    travel_tips = 'The sea here drops off quickly — the waves are stronger than they look. Swim near the river mouth where it''s shallower. The Rekawa turtle visits are led by local conservation staff; tips support their work. Cash is limited in Tangalle; hit the ATM in town. The mosquitoes can be fierce after sunset.',
    nearby_travel_times = 'Rekawa: 10 minutes. Mulkirigala: 30 minutes. Matara: 1 hour. Yala: 1.5 hours. Galle: 1.5 hours.',
    works_well_with = 'Yala, Udawalawe, Mirissa',
    cta_text = 'We know a quiet villa in Tangalle with a private stretch of sand. No crowds, no schedule, just the beach.',
    faq_json = '[{"q":"Is Tangalle better than Mirissa?","a":"If you want quiet and empty beaches, Tangalle wins. If you want restaurants and nightlife, Mirissa."},{"q":"Can I swim at Tangalle?","a":"Yes but the sea is rougher than the west coast. Choose a sheltered spot and watch the currents."},{"q":"Are there turtles at Tangalle?","a":"Rekawa Beach has a conservation project. Turtles nest most nights. Guided visits only."}]'
WHERE slug = 'tangalle'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'A mountain you climb before dawn to watch the sun crack the horizon. Sri Lanka''s most sacred peak draws pilgrims and hikers alike.',
    intro = 'Adam''s Peak — Sri Pada — rises 2,243 metres above the tea plantations of the central highlands. Pilgrims have climbed this mountain for over a thousand years. The footprint-shaped depression at the summit is claimed by Buddhists, Hindus, Muslims, and Christians. Everyone climbs for the sunrise. The trail starts in the dark, passes through a lantern-lit path of tea stalls, and ends at a summit where the whole island seems to unfold below. The stair count varies by who''s counting — most people say about 5,500 steps. It''s a pilgrimage, a hike, and a sunrise viewing platform rolled into one. There''s nothing else like it.',
    why_visit = 'The moment at the top when the sun appears and the shadow of the peak stretches across the valley is one of the great experiences in Sri Lanka. The climb itself is social — strangers encourage each other, share food, sing. The tea stalls along the way are run by families who''ve been there for generations. It''s not a difficult climb but it''s relentless. The sense of achievement at the top is real.',
    things_to_do = 'Start the climb from Dalhousie at 2 AM. Reach the summit for sunrise. Ring the bell at the top. Visit the footprint shrine. Watch the shadow of the peak spread across the landscape. Have hot tea and a snack from the vendors. Walk down (take it slow — the knees will thank you). Visit the small museum at the base.',
    best_time = 'December to May is the official pilgrimage season. The full moon nights in December and January are the busiest — the trail is lit and the crowd is enormous. February and March offer the best weather. The off-season means rain, fog, and leeches, but also solitude.',
    how_to_get_there = 'About 180 kilometres from Colombo via Hatton. Turn off at Maskeliya for Dalhousie (also called Nallathanniya). Buses run from Colombo to Hatton, then a local bus. The train from Colombo to Hatton is scenic. From Hatton, a tuk-tuk to Dalhousie.',
    suggested_itinerary = 'Arrive in Dalhousie by late afternoon. Sleep early. Climb at 2 AM. Back down by 8 AM. Breakfast and onwards to Nuwara Eliya or Kandy. One night is all you need. You won''t sleep much anyway.',
    where_to_stay = 'Dalhousie has basic guesthouses aimed at pilgrims. Expect cold showers and simple rooms. Slightly Chilled is popular. Maskeliya and Hatton have better options. If you want comfort, stay in Hatton and drive to the base for the climb.',
    travel_tips = 'Bring a headlamp — the path is well-marked but unlit. A light jacket for the summit (it''s cold, even in season). Gloves for the chains near the top — they''re cold and rough. The chain section is steep but short. Don''t attempt the climb if there''s lightning nearby. The summit is exposed.',
    nearby_travel_times = 'Maskeliya: 15 minutes. Hatton: 45 minutes. Nuwara Eliya: 1.5 hours. Kandy: 3 hours. Colombo: 4 hours.',
    works_well_with = 'Nuwara Eliya, Hatton, Kandy, Ella',
    cta_text = 'We can organise the early-morning taxi, the headlamps, and the breakfast that''s waiting when you get back down.',
    faq_json = '[{"q":"Is this the same climb as Sri Pada?","a":"Yes. Adam''s Peak and Sri Pada are the same mountain. Different names for different traditions."},{"q":"How fit do I need to be?","a":"The climb is steps all the way — 5,500 of them. It''s not technical but you need stamina."},{"q":"Is it safe to climb alone?","a":"Yes, the trail is busy enough that you''re never really alone."}]'
WHERE slug = 'adams-peak'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'The crossroads of the central province. A market town that''s nobody''s final destination but everyone passes through.',
    intro = 'Kurunegala sits at the junction of several main highways, about 90 kilometres from Colombo. It''s a market town with a large lake and a rock formation that looks like an elephant drinking from it. That rock is called Elephant Rock — local legend says a demon cursed a herd of elephants and turned them to stone. The town is busy, functional, and largely ignored by tourists. That''s a shame. The lake at sunset is pleasant. The local food is good. The Dharmaraja Dagoba on top of a nearby rock gives a sweeping view of the region. It''s a place that''s honest about being unremarkable, and there''s something refreshing about that.',
    why_visit = 'It''s the kind of town that tourists miss. If you want a taste of a regular Sri Lankan regional capital — not a tourist town, not a resort — Kurunegala gives it to you. The market is excellent. The Athugala (Elephant Rock) climb is a 20-minute hike with a good view. The Buddhist temples have some interesting modern murals. And the food is cheap and unfussy.',
    things_to_do = 'Climb Elephant Rock (Athugala) for the view. Walk around the lake. Explore the market. Visit the Dharmaraja Dagoba. Eat kottu roti and rice and curry at a local restaurant. Visit the Ridi Viharaya (Silver Temple) — 30 minutes away, one of the oldest cave temples in the country.',
    best_time = 'Year-round. The town works in any season. January to April is driest. The lake looks best in the wet season.',
    how_to_get_there = '90 kilometres from Colombo on the A6 highway — about 2 hours by car. Buses run from Colombo, Kandy, and Dambulla. The railway line from Colombo to Kandy passes nearby but doesn''t serve Kurunegala directly.',
    suggested_itinerary = 'Half a day is enough. Stop for lunch, climb the rock, walk the lake, and carry on. It''s a rest stop, not a destination. If you stay a night, the Ridi Viharaya makes a good afternoon trip.',
    where_to_stay = 'The town has business hotels aimed at domestic travellers. Hotel Blue River is decent. The Mango Garden Homestay is a homely option. You''re not coming here for the hotel.',
    travel_tips = 'The traffic in the centre is chaotic. Park outside and walk. The rock climb is closed during heavy rain. The lake walk is fine but don''t swim. The rice and curry in a local restaurant will cost 300-400 LKR.',
    nearby_travel_times = 'Kandy: 1 hour. Dambulla: 1 hour. Colombo: 2 hours. Anuradhapura: 2.5 hours.',
    works_well_with = 'Kandy, Dambulla, Anuradhapura',
    cta_text = 'We can route your drive through Kurunegala for lunch and a leg-stretch that''s better than a highway rest stop.',
    faq_json = '[{"q":"Is Kurunegala worth visiting?","a":"As a stopover, yes. It''s an honest market town with good food and a nice lake."},{"q":"How long should I spend here?","a":"A couple of hours. Climb the rock, walk the lake, eat lunch, move on."},{"q":"What''s Elephant Rock?","a":"A large rock formation locals call Athugala. The 20-minute climb gives a view over the town."}]'
WHERE slug = 'kurunegala'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'A remote town on the northwest coast where the focus is birdlife, baobab trees, and the sea.',
    intro = 'Mannar sits on the northwest coast, connected to the mainland by a causeway. It''s a dry, dusty town with a long history of colonial occupation — Portuguese, Dutch, British, and even the sea. The reef here has some of the oldest pearl banks in the world. The war left its mark. The recovery is slow. What brings people here now are the birds, the beaches, and the sense of being at the edge of something. The causeway at sunset is beautiful. The baobab trees — brought by Arab traders centuries ago — dot the landscape. Mannar is not for everyone. But if you''re on a long trip and want somewhere different, it delivers.',
    why_visit = 'The birdlife is extraordinary. The Mannar wetlands and the nearby Giant''s Tank reservoir attract thousands of migratory birds from November to February. Flamingos, pelicans, and painted storks are common. The baobab trees are one of Sri Lanka''s oddities — one near Pallimunai is over 700 years old. The beaches on the islands off the coast are pristine and empty. The ruins of the Dutch fort add historical texture. And the paan (bread) in Mannar is a local speciality worth trying.',
    things_to_do = 'Birdwatch at the Mannar wetlands and Giant''s Tank. Visit the 700-year-old baobab tree. Explore the Dutch Fort ruins. Take a ferry to the islands — Analaitivu, Nainativu. Visit the Nainativu Nagapooshani Amman Temple (one of the oldest Hindu temples). Eat fresh seafood at the harbour. Watch the sunset over the causeway. Visit the Mannar lighthouse.',
    best_time = 'November to February is the bird migration season — the best time to visit. January to April is the dry season with good weather. May to September the monsoon hits this coast hard.',
    how_to_get_there = 'About 300 kilometres from Colombo — 5 hours by car via Puttalam and the coastal road. Buses run from Colombo, Anuradhapura, and Jaffna. The train from Colombo to Mannar takes about 7 hours.',
    suggested_itinerary = 'Two nights is right. Day one: arrive, walk the town, sunset at the causeway. Day two: birdwatching in the morning, baobab tree and fort in the afternoon, dinner at the harbour. Day three: ferry to the islands and back.',
    where_to_stay = 'Accommodation in Mannar is basic. The Palmyrah House is the best option — a heritage house turned hotel. Mannar Beach Resort is decent. For budget, the town has a few guesthouses. Book ahead — options are limited.',
    travel_tips = 'The sun is harsh — bring a hat and sunscreen. The roads outside town are rough. The ferry schedules to the islands vary; ask at the port. The bird season is strictly November to February. Outside that, the wetlands are quiet. Cash is essential; credit cards are accepted in very few places.',
    nearby_travel_times = 'Jaffna: 3 hours. Anuradhapura: 3 hours. Puttalam: 2 hours. Colombo: 5 hours.',
    works_well_with = 'Jaffna, Anuradhapura, Puttalam',
    cta_text = 'Mannar is an odd, wonderful detour. We can plan the route, the ferry, and the birder''s logbook.',
    faq_json = '[{"q":"Is Mannar safe to visit?","a":"Yes. The area was affected by the war but is now peaceful and safe for travel."},{"q":"When is the best time for birds?","a":"November to February is peak migration season with thousands of birds."},{"q":"Are there beaches in Mannar?","a":"The best beaches are on the islands off the coast — white sand and quiet."}]'
WHERE slug = 'mannar'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'A shallow lagoon on the east coast where the water is bath-warm and the beach goes on forever.',
    intro = 'Pasikudah is a resort strip on the east coast, about 35 kilometres from Batticaloa. The bay is a shallow, protected lagoon that stays waist-deep for hundreds of metres. You can walk out for ten minutes and the water is still at your chest. It''s like swimming in a pool, except the pool is the Indian Ocean and the colour is turquoise. The beach is a long stretch of white sand lined with big hotels. It''s the most resort-oriented beach on the east coast — package tourists, water sports, and all-inclusive wristbands. If you want a beach where you can wade out forever, this is your place.',
    why_visit = 'The swimming conditions are unique. You can walk out to the reef break and the water never goes above your shoulders. It''s safe, warm, and clear. The beach is well-maintained. The water sports are decent — kayaking, windsurfing, and jet skis. It''s also a good base for exploring the Batticaloa area, which has a different culture and history from the rest of the east coast.',
    things_to_do = 'Swim and wade — the main activity. Walk the length of the bay. Try water sports at the hotel operators. Visit the Batticaloa Fort (30 minutes away). Take a boat trip on the Batticaloa lagoon. Visit the Kallady Beach at the bridge — locals say singing fish can be heard here on full moon nights. Eat seafood at a beachfront restaurant.',
    best_time = 'April to October is the east coast season. May to September is the best weather. November to March is the monsoon — the hotels mostly shut down and the sea gets rough. The season is shorter than the south coast.',
    how_to_get_there = 'About 300 kilometres from Colombo — 6 hours by car via the A4 highway through Mahiyanganaya or the A5 through Badulla. The road through Mahiyanganaya is shorter but windier. Buses run from Colombo to Batticaloa, then a local bus or tuk-tuk the remaining 35 kilometres.',
    suggested_itinerary = 'Three to five nights for a beach holiday. Two nights is enough to see the area. The rhythm is same as any beach destination: swim, eat, rest, repeat. Add a day trip to Batticaloa town and the fort.',
    where_to_stay = 'The beach is dominated by big resort hotels. Uga Bay is the luxury option — boutique and beautiful. Pasikudah Hotel by Palm Beach is the classic resort. Anilana Pasikudah is good mid-range. There''s very little budget accommodation; Pasikudah is designed for package tourism.',
    travel_tips = 'The resort restaurants are pricey. Walk to the smaller restaurants at the south end of the bay for cheaper food. The water is shallow so snorkelling is limited. The coral is at the edge of the bay near the reef. The area has a strong Muslim community — dress modestly when outside the resort. The Sunday market at Batticaloa is worth the trip.',
    nearby_travel_times = 'Batticaloa: 30 minutes. Kalkudah: 5 minutes (same bay). Arugam Bay: 1.5 hours. Trincomalee: 2 hours.',
    works_well_with = 'Batticaloa, Arugam Bay, Trincomalee, Polonnaruwa',
    cta_text = 'We can book the resort, the transfers, and a driver who knows the right route through the winding hill roads.',
    faq_json = '[{"q":"Is Pasikudah good for families?","a":"Excellent. The shallow, calm water is perfect for children. No waves to worry about."},{"q":"Is Pasikudah similar to Mirissa?","a":"Not really. Pasikudah is more resort-focused and the water is much shallower."},{"q":"Can I see dolphins here?","a":"Dolphins are spotted in the bay occasionally. Batticaloa lagoon has more wildlife."}]'
WHERE slug = 'passikudah'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'An east coast city with a lagoon, a fort, and a history that draws from the sea.',
    intro = 'Batticaloa sits on a lagoon on the east coast, about 100 kilometres south of Trincomalee. It''s a Tamil-speaking town with Portuguese, Dutch, and British colonial layers. The fort on the lagoon is a star-shaped Dutch fort that''s still intact. The lagoon itself is the heart of the town — fishing boats, stilt fishermen, and bird life. The war hit Batticaloa hard. It''s still a scarred place. But it''s rebuilding. The people are warm. The food is excellent — Batticaloa is famous for its crab curry and its thala (kurakkan) roti. It''s not a tourist town. It doesn''t try to be. That''s its appeal.',
    why_visit = 'The fort is one of the best Dutch forts in Sri Lanka — well-preserved, free to enter, and quiet. The Batticaloa lagoon is beautiful, particularly at sunset when the stilt fishermen are silhouetted. The Kallady Bridge is the spot where locals claim you can hear "singing fish" on full moon nights. The food is a genuine draw: the Muslim quarter has some of the best biryani in Sri Lanka. And the beaches to the north — Kallady Beach, Pasikudah, Kalkudah — are close enough for day trips.',
    things_to_do = 'Explore the Batticaloa Fort. Take a boat ride on the lagoon. Walk across the Kallady Bridge at sunset. Visit the St. Mary''s Cathedral — a striking white Gothic church. Eat biryani and crab curry in the Muslim quarter. Visit the Batticaloa market. Take a day trip to Pasikudah or Kalkudah beaches. Listen for the singing fish at full moon (it''s a real phenomenon, though scientists debate what causes it).',
    best_time = 'April to October is the dry season on the east coast. June to September is the best window. November to March brings the monsoon. The lagoon tours run year-round but are best in the dry season.',
    how_to_get_there = 'About 300 kilometres from Colombo — 6 hours by car via the A4 highway. Trains run from Colombo to Batticaloa (about 7 hours, an overnight train is available). Buses from Colombo, Kandy, and Trincomalee.',
    suggested_itinerary = 'Two nights. Day one: arrive, explore the fort and the town. Day two: lagoon boat ride in the morning, beach trip in the afternoon. Day three: market visit and head north or south.',
    where_to_stay = 'Batticaloa has limited but improving accommodation. Hotel Aalia is the best option — new, clean, with a pool. Batticaloa Holiday Inn is decent mid-range. For budget, the guesthouses near the bus station. The Dutch Fort area has a few simple places.',
    travel_tips = 'The fort is free and open all day. Go at sunset for the best light. The lagoon boat tours are negotiable — bargain for a longer trip. The singing fish phenomenon is best asked about locally. The town has a curfew history but that''s not current; check local advice. Secure your belongings — the market can be busy.',
    nearby_travel_times = 'Pasikudah: 30 minutes. Kalkudah: 35 minutes. Arugam Bay: 2 hours. Trincomalee: 2 hours. Kandy: 5 hours.',
    works_well_with = 'Pasikudah, Arugam Bay, Trincomalee, Polonnaruwa',
    cta_text = 'We can arrange a guide for Batticaloa lagoon, the fort history, and the food spots the internet doesn''t list.',
    faq_json = '[{"q":"Is Batticaloa affected by the war?","a":"The war ended in 2009. The town is safe but some areas still show damage."},{"q":"What is Batticaloa known for?","a":"The Dutch fort, lagoon, crab curry, and the legend of singing fish at Kallady Bridge."},{"q":"Can I swim in the lagoon?","a":"The lagoon is not clean enough for swimming. Go to Pasikudah or Kalkudah for the beach."}]'
WHERE slug = 'batticaloa'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'A busy town at the mouth of the Nilwala River. The market is massive, the fort is Dutch, and the beach stretches east.',
    intro = 'Matara is the last major town on the south coast before the road goes inland. It''s a working city — trade, fishing, and local government. The Dutch Fort at the river mouth is smaller than Galle''s but less touristy and just as atmospheric. The market along the Nilwala River is huge and chaotic. The beach is a long strip of sand facing south. The Parey Dewa temple sits on a rock island in the surf, connected by a bridge. It feels like a defensive outpost. Matara doesn''t get many tourists staying overnight. Most rush through on the way to Mirissa or Tangalle. They''re missing a decent food scene and the best fish market on the south coast.',
    why_visit = 'The Matara Fort is the underrated attraction — walk the ramparts, visit the church, sit in the cafe overlooking the river mouth. The Parey Dewa temple is photogenic. The fish market at the harbour is the real deal: the catch comes in at dawn and the auction is pure theatre. The food in Matara is excellent — the local fish curry, coconut sambol, and egg hoppers are authentic and cheap. The Nupe Market across the river is one of the oldest in Sri Lanka.',
    things_to_do = 'Walk the Matara Fort ramparts. Cross the bridge to Parey Dewa temple. Visit the fish market at dawn. Explore the Nupe Market. Walk the beach from the river mouth eastwards. Eat at the family-run restaurants in the fort area. Visit the Star Fort — a tiny hexagonal Dutch fortification up the river.',
    best_time = 'November to April is the dry season. January to March is ideal. May to October is the monsoon — the sea is rough and the beach empties. The fort and temples work in any weather.',
    how_to_get_there = '160 kilometres from Colombo — 2 hours on the Southern Expressway. Trains from Colombo to Matara take about 3 hours — the end of the coastal line. Buses from Colombo, Galle, and all south coast towns.',
    suggested_itinerary = 'One night is plenty. Arrive in the afternoon, walk the fort, dinner by the river. Morning fish market, Parey Dewa temple, then onward. It works as a lunch stop between Galle and Tangalle.',
    where_to_stay = 'Matara has a few good options. Bay Vista is a boutique guesthouse with a view. Fort House is atmospheric in the old fort. For budget, the guesthouses along the beach road. Matara is not a resort town — the accommodation reflects that.',
    travel_tips = 'The fish market peaks at 5-6 AM. If you''re not awake for it, you''ve missed the best part of Matara. The Parey Dewa temple has a strict dress code. The beach at Matara is not as clean as the resort beaches to the east. The best food in Matara is at the small restaurants run by Tamil families in the fort area.',
    nearby_travel_times = 'Mirissa: 20 minutes. Weligama: 15 minutes. Tangalle: 1 hour. Dondra Head: 15 minutes. Galle: 45 minutes.',
    works_well_with = 'Mirissa, Galle, Tangalle, Dondra Head',
    cta_text = 'We know a fish market tour in Matara that starts at 5 AM and ends with breakfast at a place that does the best fish curry on the coast.',
    faq_json = '[{"q":"Is Matara worth visiting?","a":"As a stop between Galle and Tangalle, yes. The fort and fish market are worth an hour or two."},{"q":"What''s the Parey Dewa temple?","a":"A Buddhist temple on a rock island in the sea, connected by a footbridge. Best visited at sunset."},{"q":"Can I swim at Matara beach?","a":"The main beach is okay but rougher than Mirissa. The river mouth currents are dangerous."}]'
WHERE slug = 'matara'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'The gem capital of Sri Lanka. A town built on sapphires, rubies, and the hopes of miners who dig by hand.',
    intro = 'Ratnapura means City of Gems. It sits in a valley surrounded by the rainforests of the Sabaragamuwa province, about 100 kilometres southeast of Colombo. The town is the centre of Sri Lanka''s gem trade — sapphires, rubies, cat''s eyes, and star stones are pulled from the mud of the surrounding fields. The mining is largely small-scale and artisanal. Men dig pits by hand, haul up buckets of gravel, and wash it in baskets. The Gem Museum in town is excellent. The Ratnapura Market has a gem section that''s fascinating even if you''re not buying. It''s not a pretty town. The streets are congested and the river floods. But it''s the most unique town in the hill country.',
    why_visit = 'The gem connection is the draw. You can visit a working mine, see the gem-cutting process, and shop at the source. The Gem Museum explains the geology and the trade. The surrounding countryside has Sinharaja Rainforest to the south, Udawalawe to the east, and Adam''s Peak to the north. The Mahaweli River rushes through the town and floods it regularly — the locals consider it part of life. The Buddhist temple on the hill above town has a giant Buddha statue and a good view.',
    things_to_do = 'Visit the Ratnapura National Gem Museum. Tour a working gem mine. Watch gem cutting and polishing. Shop at the gem market (know what you''re buying or bring someone who does). Visit the Maha Saman Devale — a temple dedicated to the deity Saman. Hike to the Bopath Ella waterfall (30 minutes from town). Visit the Sinharaja Rainforest (the nearest entrance is 30 minutes away).',
    best_time = 'January to April is the dry season. The mines are more active, the roads are better, and Sinharaja is accessible. May to November is the wet season — Ratnapura is one of the rainiest places in Sri Lanka. The forests are lush but the driving is difficult.',
    how_to_get_there = 'About 100 kilometres from Colombo — 2.5 hours by car on the A4 highway. Buses run from Colombo, Kandy, and Nuwara Eliya. The Ratnapura bus station is a hub for the southern hill country. The nearest train station is in Avissawella, about an hour away.',
    suggested_itinerary = 'One night is enough. Arrive, visit the museum in the afternoon, tour a mine the next morning, and head out. Use Ratnapura as a base for Sinharaja or Adam''s Peak rather than a destination itself.',
    where_to_stay = 'Ratnapura has practical accommodation. Hotel Nippon is the most comfortable. Ratnaloka Mountain Lodge has views. For budget, the guesthouses near the bus station are basic. There''s nothing luxurious about staying here.',
    travel_tips = 'If you''re buying gems, know that the quality varies wildly. The museum has a certified dealer list. Don''t buy from touts on the street. The mines are safe to visit in the dry season. The rainy season floods the pits. The flood-prone areas are well-known — ask before parking near the river. Sinharaja needs a separate day.',
    nearby_travel_times = 'Sinharaja Rainforest: 30 minutes to the entrance. Udawalawe: 1.5 hours. Adam''s Peak: 2 hours. Colombo: 2.5 hours. Kandy: 3 hours.',
    works_well_with = 'Sinharaja, Udawalawe, Adam''s Peak, Colombo',
    cta_text = 'We can arrange an ethical mine tour in Ratnapura — no pressure to buy, just learning about where the stones come from.',
    faq_json = '[{"q":"Can I buy sapphires in Ratnapura?","a":"Yes, but bring a knowledgeable companion or stick to certified dealers at the museum."},{"q":"Is it safe to visit the mines?","a":"In the dry season, yes. Some mines are open to visitors with a guide."},{"q":"How rainy is Ratnapura?","a":"It''s one of the wettest towns in Sri Lanka. Annual rainfall exceeds 5,000 mm."}]'
WHERE slug = 'ratnapura'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;

UPDATE destinations
SET excerpt = 'A paddy-farming district in the deep southeast. Rice paddies, lakes, and a pace of life that''s slower than anywhere.',
    intro = 'Ampara sits at the edge of the dry zone, about 60 kilometres south of Batticaloa. It''s the administrative capital of its district and the gateway to the eastern plains. The town itself is straightforward — wide streets, government buildings, and a market. The surrounding countryside is gorgeous: paddy fields that flood green in the wet season, ancient tanks (reservoirs) built by kings, and the massive Senanayaka Samudra — the largest manmade lake in Sri Lanka. Wild elephants wander the farmland at night. Gal Oya National Park is right here, the only park in Sri Lanka where you see elephants swimming between islands. Ampara is not on the tourist trail. It''s a real Sri Lankan regional town.',
    why_visit = 'Gal Oya National Park is the headline. The boat safari on the Senanayaka Samudra reservoir offers elephant sightings you can''t get anywhere else — the elephants actually swim from island to island. The park also has leopards, sloth bears, and the endemic bird species. The Inginiyagala ancient temple nearby has a 1,600-year-old statue that still gets daily offerings. The rice paddy landscapes in the surrounding villages are beautiful at golden hour.',
    things_to_do = 'Take a boat safari at Gal Oya National Park (morning is best for elephants). Visit the Gal Oya park office for guided treks. Visit the Inginiyagala temple and the ancient Buddha statue. Walk the Senanayaka Samudra dam — the view across the lake is huge. Birdwatch along the wetlands. Explore the paddy fields and villages around town. Visit the Kumana National Park extension (south of Ampara).',
    best_time = 'January to April is the dry season. Elephants are most visible around the water. May to September is the dry zone rain season — the park is lush and beautiful. October to December brings the northeast monsoon. The park closes for a period around November; check ahead.',
    how_to_get_there = 'About 340 kilometres from Colombo — 6 hours by car via the A4 highway through Monaragala. Buses run from Colombo, Batticaloa, and Kandy. The road from Pottuvil to Ampara is scenic but slow.',
    suggested_itinerary = 'Two nights. Day one: arrive, visit the Inginiyagala temple, sunset at the reservoir. Day two: Gal Oya boat safari, afternoon village walk. Day three: morning birdwatching, then onwards.',
    where_to_stay = 'Accommodation is limited and basic. Gal Oya Lodge is the best option — eco-lodge, good food, run by conservationists. For budget, the guesthouses in town. There''s no luxury here. Book Gal Oya Lodge well in advance.',
    travel_tips = 'The boat safari at Gal Oya is not like Yala. It''s quieter, deeper in the park, and more intimate. The elephants swimming between islands is a real thing, not a myth. The mosquitoes in the evening are fierce. The road from Ampara to Batticaloa is remote — fuel up before you go. The Inginiyagala temple is a living site; dress appropriately.',
    nearby_travel_times = 'Gal Oya National Park: 30 minutes. Inginiyagala: 15 minutes. Batticaloa: 1.5 hours. Arugam Bay: 2 hours. Kandy: 5 hours.',
    works_well_with = 'Arugam Bay, Batticaloa, Yala',
    cta_text = 'Gal Oya is the most unique safari in Sri Lanka. We can arrange the boat, the guide, and the accommodation at the park edge.',
    faq_json = '[{"q":"Do elephants really swim in Gal Oya?","a":"Yes. During the dry season, elephants swim between islands in the reservoir. It''s unique to this park."},{"q":"Can I do Gal Oya as a day trip from Arugam Bay?","a":"It''s a tough day — 2 hours each way by road. Overnight is better."},{"q":"Is Gal Oya busy?","a":"Almost empty compared to Yala. You''ll share the park with very few jeeps."}]'
WHERE slug = 'ampara'
  AND CHAR_LENGTH(COALESCE(excerpt, '')) < 550;
